INSERT INTO `courses` (`id`, `title`, `short_description`, `features`, `image_path`, `page_url`, `badge_text`, `course_type`, `slug`, `start_date`, `end_date`, `enrollment_open`, `manual_close`, `created_at`, `updated_at`) VALUES
(1, 'Curso de CAT Tools e Tecnologias da Tradução', 'Neste curso você vai aprender a usar ferramentas que aumentam a sua produtividade, reduzem os erros de uniformidade e evitam o retrabalho ao reaproveitar trechos que já foram traduzidos.', 'Carga horária: 15 horas\r\nAulas ficam gravadas para consulta\r\nDisponibilidade das gravações por 6 meses', '/images/cursos/posters/course_68fe3ed87a7db_banner_cat (1).png', 'https://v.translators101.com/cursos/cattools.php', 'Curso completo', 'Ao vivo', 'cattools', '2025-09-20', '2025-10-20', 0, 1, '2025-10-20 22:22:48', '2025-10-26 15:31:45'),
(2, 'Supercurso de Tradução de Jogos', 'O SUPERCURSO é ministrado por uma equipe de especialistas atuantes no mercado de tradução e localização de jogos.\r\nUm dos cursos mais elogiados entre os promovidos pela Translators101!\r\nAprovado por mais de 150 alunos.', 'Dez encontros de 2 horas — 20 horas no total\r\nAcesso às gravações por seis meses\r\nTrês projetos práticos de localização ao longo do curso\r\nCom certificado de conclusão', '/images/cursos/posters/course_68fe3e0e792bc_Cursos - SC8.png', 'https://v.translators101.com/cursos/supercurso8.php', 'Curso completo', 'Ao vivo', 'supercurso8', '2025-10-01', '2025-11-03', 1, 1, '2025-10-20 22:22:48', '2025-10-26 15:28:14'),
(3, 'Admiráveis Ferramentas Novas', 'Descubra como integrar o ChatGPT e a ModernMT a seu fluxo de trabalho para aprimorar suas traduções e aproveitar as novas possibilidades que as ferramentas oferecem.\r\nCrie bots para ajudar com tarefas na tradução.\r\nUse o NotebookLM para criar glossários e estudar temas para suas traduções e interpretações.', 'Três módulos\r\nCertificado\r\nCurso atualizado', '/images/cursos/posters/course_68fe3cb800c4c_banner_afn.png', 'https://v.translators101.com/cursos/admiraveis.php', 'Workshop', 'Gravado', NULL, '2025-10-01', '0000-00-00', 1, 0, '2025-10-26 15:08:13', '2025-10-26 15:22:32');
