INSERT INTO `lectures` (`id`, `title`, `speaker`, `speaker_minibio`, `description`, `duration_minutes`, `embed_code`, `thumbnail_url`, `image`, `category`, `tags`, `created_at`, `updated_at`, `is_featured`, `is_live`, `language`, `level`) VALUES
('00146049-865a-493c-86b7-970f3f8e1bea', 'S08E09 — Como integrar a ModernMT a seu fluxo de trabalho — Val Ivonica', 'Val Ivonica', NULL, '', 97, '<div id=\"panda-00146049-865a-493c-86b7-970f3f8e1bea\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E09-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('0109af5c-f3bf-448a-97ce-ce805deaff2e', 'Especial #ITD 2020 — O tradutor para dublagem, o texto traduzido e o estúdio', 'Paulo Noriega', '', 'Não há dublagem sem tradutor. Essa figura tão importante é a base de todo o processo e, diante disso, a palestra tem como objetivo se debruçar sobre alguns dos principais aspectos que envolvem esse profissional e a sua dinâmica dentro do mundo da dublagem, entre eles: \r\n\r\n- O que é necessário para se ter uma tradução para dublagem de excelência? \r\n\r\n- Como se dá a dinâmica entre o tradutor e o estúdio de dublagem? \r\n\r\n- O texto do tradutor: afinal, de quem é? É mesmo do tradutor? Dos dubladores? Do cliente?', 64, '<div id=\"panda-0109af5c-f3bf-448a-97ce-ce805deaff2e\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Paulo-HR-1536x864.jpeg', NULL, 'TAV', '[\"\"]', '2025-07-14 19:31:00', '2025-09-23 10:59:09', 0, 0, '', ''),
('016fbbb2-c481-4a1d-a5cc-bc9c4ded57dd', 'I2B ', 'William Cassemiro', NULL, '', 113, '<div id=\"panda-016fbbb2-c481-4a1d-a5cc-bc9c4ded57dd\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/William-Qnt-vale_-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('0172db77-fa26-47ec-b606-7b579e0fd177', 'S06E10 — O tradutor profissional e a globalização — Jorge Rodrigues', 'Jorge Rodrigues', NULL, '', 52, '<div id=\"panda-0172db77-fa26-47ec-b606-7b579e0fd177\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E10-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0199c136-dc09-4be2-b449-e2c0308317f8', 'Spin-off_09 ', 'Priscila Stuani', NULL, 'Nesta oficina, Priscila Stuani falará sobre o que é CNV (Comunicação Não Violenta) e como aplicá-la em nosso cotidiano.\nA CNV nos ajuda a entender como lidar de modo mais saudável com nossas emoções, através de reflexões e reações mais conscientes. Em diferentes cenários, a comunicação não violenta favorece a manifestação e interação de todos envolvidos, pois cria um ambiente acolhedor.\nHaverá um momento de \"mão na massa\" onde colocaremos em prática os 4 pilares da CNV (não julgar, identificar sentimentos, assumir responsabilidades e fazer pedidos) para contribuir na construção de repertório pautado na CNV.', 137, '<div id=\"panda-0199c136-dc09-4be2-b449-e2c0308317f8\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/SPIN-OFF_09-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-09-23 20:23:21', 1, 0, NULL, NULL),
('032f60c9-7ee5-4f5b-9fe8-ec9a589eae27', 'S02E03 — Cinco tipos diferentes de tradução — Eneide Moreira', 'Eneide Moreira', NULL, 'Palestra de Eneide Moreira', 63, '<div id=\"panda-307882f8-f303-49c6-8652-a7902e571a8a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E03-2.jpeg', NULL, 'Geral', '[\"geral\"]', '2025-06-10 14:56:57', '2025-06-11 19:06:33', 0, 0, NULL, NULL),
('04174e33-7754-4ef1-b161-125a635b7e24', 'S06E29 — Exemplos práticos de multiculturalismo na tradução de inglês e português — Stephan Hughes', 'Stephan Hughes', NULL, 'O multiculturalismo é uma ponte entre culturas e a tradução é uma ferramenta importante para a troca de conhecimentos e experiências. A tradução é vista por Spivak (2005) como um relacionamento ético com o texto do outro. A presente palestra visa explorar as nuances e os desafios do multiculturalismo entre o inglês e o português, assim como demonstrar a importância da competência intercultural e estratégias sociopolíticas para se ter uma tradução multicultural mais precisa e eficiente.', 73, '<div id=\"panda-04174e33-7754-4ef1-b161-125a635b7e24\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E29-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('058e9da1-305d-4cc5-b9b8-f24777de3214', 'Especial #ITD 2020 — T101 explica WordFast', 'Daniel Estill', NULL, 'Conheça o básico da ferramenta WordFast', 84, '<div id=\"panda-058e9da1-305d-4cc5-b9b8-f24777de3214\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Daniel-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('0595bfe4-4224-41b2-8e8c-3f86108ddd32', 'S08E12 — Missão impossível? Não! Como gerenciar projetos de tradução sem pirar — Jerusa Marreti', 'Jerusa Marreti', NULL, '', 101, '<div id=\"panda-0595bfe4-4224-41b2-8e8c-3f86108ddd32\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E12-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-09-23 20:20:13', 1, 0, NULL, NULL),
('071cb704-9a01-441e-9682-298f5fe2016f', 'S05E22 — Interação humano-computador na tradução: dos benefícios aos desafios — Rossana Cunha', 'Rossana Cunha', NULL, 'O potencial da interação humano-computador para a tradução tem mostrado benefícios tanto para os usuários - que produzem traduções de alta qualidade - quanto para os modelos de processamento de linguagem natural, que conseguem aprimorar seus resultados a partir do feedback fornecido pelos usuários. O objetivo desta palestra é explorar as interseções da interação humano-computador (IHC), inteligência artificial e tradução automática, além de aplicações e a forma como o tema é abordado ela mídia. Espera-se assim elucidar os benefícios e desafios do uso da IHC na área de tradução, além de promover uma visão geral sobre o tema.', 90, '<div id=\"panda-071cb704-9a01-441e-9682-298f5fe2016f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E22-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('079fe631-5e46-4029-8ab6-393e45662487', 'Maratona — Negociação avançada', 'André Ribeiro', NULL, 'Negociação é um jogo. Entre para vencer. Omitir não é mentir. Não fale tudo. Os diferentes cenários da negociação. Comando da negociação: você e você. O cliente que paga bem e sabe que paga bem (a galinha dos ovos de ouro). Acompanhamento da negociação. Estudos de casos reais.', 109, '<div id=\"panda-079fe631-5e46-4029-8ab6-393e45662487\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Maratona-Negociacao-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('07d8be12-d36e-4933-868a-abccee761e98', 'S06E45 — Traduzindo Clássicos — Petê Rissatti', 'Petê Rissatti', NULL, 'A tradução de clássicos é o que mantém vivos livros que tiveram grande importância para uma época e, por sua longevidade, também para a cultura mundial. Nesta palestra, vamos entender o que é um clássico, conhecer um pouco do processo de tradução de um livro considerado clássico para um público contemporâneo, além do conceito de direito autoral e suas regras. Será um bate-papo para quem se interessa por literatura e tradução, para quem está dando os primeiros passos e para quem já tem uma carreira consolidada, mas quer saber mais desse tipo de tradução.', 93, '<div id=\"panda-07d8be12-d36e-4933-868a-abccee761e98\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E45-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('08493a73-51a2-41ec-9735-d35e1b03e8f4', 'CULT-Estácio ', 'Juliana Lima', NULL, '', 56, '<div id=\"panda-08493a73-51a2-41ec-9735-d35e1b03e8f4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('088082bb-d55f-4ded-a693-ef85cb6bbdd4', 'Spin-off 23 ', 'Avellan', NULL, '', 44, '<div id=\"panda-088082bb-d55f-4ded-a693-ef85cb6bbdd4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('093581eb-f813-4040-a7ef-32ce9cf682be', 'S05E08 — Jogo de palavras: localização de jogos de tabuleiro — Paula Pizauro', 'Paula Pizauro', NULL, 'Conheça mais sobre os desafios, a comunidade gamer e o mercado da localização de jogos de tabuleiro.', 148, '<div id=\"panda-093581eb-f813-4040-a7ef-32ce9cf682be\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E08-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0ad295c5-3f46-422d-9c79-1a0dcbdde752', 'S04E32 — Legendagem: Descomplicando a Sincronia no Subtitle Edit — Matheus Maggi', 'Matheus Maggi', NULL, 'Sincronia de legendas é um assunto que faz muitos legendadores torcerem o nariz, dizendo que chegam até a arrepiar, mas será que realmente é um bicho de sete cabeças?\nNesta palestra, o legendador Matheus Maggi vai provar que sincronizar é mais simples do que parece, além de mostrar várias maneiras de realizar os mesmos processos, dando a oportunidade de você escolher a forma que achar mais confortável.\nO objetivo é ver você dizer que a sincronia é a parte mais tranquila de uma legenda.', 96, '<div id=\"panda-0ad295c5-3f46-422d-9c79-1a0dcbdde752\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E32-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0b4f7e96-a3c5-4c6b-9418-cc2ef7073b43', 'S05E16 — Contra o terraplanismo linguístico na tradução — Rane Souza e Jorge Davidson', 'Rane Souza e Jorge Davidson', NULL, '', 102, '<div id=\"panda-0b4f7e96-a3c5-4c6b-9418-cc2ef7073b43\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E16-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0b98b64e-2bfc-46e2-90c1-7240793c3baf', 'S04E34 — EULA: usando a internet a nosso favor — Fernanda Vitarelli', 'Fernanda Vitarelli', NULL, 'Já se deparou por aí com o termo EULA?\nO End-User Licence Agreement é um documento bastante conhecido pelos tradutores da área de tecnologia, mas com o crescimento do setor, todos nós deveríamos conhecê-lo.\nE como todo bom documento jurídico, ele não vem sem desafios. Os desafios são: Esse documento pode ser traduzido ou deve ser escrito pelo time jurídico local? Quais os impactos de um EULA mal traduzido? Qual a melhor forma de traduzir um EULA?\nTodas essas perguntas serão respondidas hoje por Fernanda Vitarelli.', 138, '<div id=\"panda-0b98b64e-2bfc-46e2-90c1-7240793c3baf\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E34-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0bfd4e52-c3f7-4656-8020-1261b129d671', 'S05E04 — Per aspera ad astra: a tradução de High Frontier 4 All — Ricardo Garcia', 'Ricardo Garcia', NULL, 'Considerado por seus fãs como um dos jogos de tabuleiro mais complexos e realistas já criados, High Frontier é um jogo altamente temático sobre a exploração, industrialização e colonização do nosso Sistema Solar. Fundamentado sobre os mais recentes conceitos e teorias da ciência, engenharia e astrofísica, o jogo aborda os aspectos científicos, tecnológicos, econômicos e políticos da exploração espacial, tornando sua tradução uma experiência única.', 99, '<div id=\"panda-0bfd4e52-c3f7-4656-8020-1261b129d671\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E04-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0d92495e-dc9c-4f87-85dc-f826cb88c2cf', 'S05E33 — Tradução de textos de turismo e viagem: características e teoria funcionalista — Sofia Pulici', 'Sofia Pulici', NULL, 'Muitos tradutores pensam que textos de turismo e viagem são genéricos e não é preciso especialização para traduzi-los, mas, quando aceitam um projeto da área, acabam tendo muitas dificuldades por não entender algumas características do texto ou sua função, tornando o trabalho penoso ou entregando menor qualidade.', 70, '<div id=\"panda-0d92495e-dc9c-4f87-85dc-f826cb88c2cf\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E33-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0e6f58cd-d400-4efa-903f-cbb95d08e127', 'S03E18 — Tradução de videogames: o ponto de vista do tradutor — Michel Teixeira', 'Michel Teixeira', NULL, 'Que abordagem um tradutor precisa adotar ao receber um trabalho de tradução de videogames: como se preparar, o que esperar, como agir em caso de dúvidas, que medidas tomar durante a tradução e após a revisão final para entregar um produto de qualidade? Nesta palestra, partindo de experiências pessoais, tento responder essas perguntas para ajudar profissionais que desejam se especializar em tradução de videogames.', 107, '<div id=\"panda-0e6f58cd-d400-4efa-903f-cbb95d08e127\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E18-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0ece69f5-8288-40fa-bd1e-890b770fc66a', 'Dicas: Pausa ', 'Renata Cassemiro', NULL, '', 1, '<div id=\"panda-0ece69f5-8288-40fa-bd1e-890b770fc66a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/PAUSA-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('0fb71581-b543-4acd-b142-073b7a7e6ab5', 'S03E23 — Amigos, amigos, trabalhos à parte: o trabalho com colegas contratantes — Daniele Fonseca', 'Daniele Fonseca', NULL, 'Muito se fala sobre o trabalho com agências ou com clientes diretos, mas e quando o contratante é um colega tradutor? Nesta palestra, pretendo abordar algumas questões de relacionamento e trabalho que ajudam a separar o pessoal do profissional, mas podem estreitar laços profissionais.', 79, '<div id=\"panda-0fb71581-b543-4acd-b142-073b7a7e6ab5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E23-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('0fbc0fbb-7eff-4d61-ba3c-ed8e57b385d0', 'S07E45 — Do manual à mesa: como explicar jogos ao público pode aprimorar as habilidades do tradutor — Jéssica Gubert e Raul Rocha', 'Jéssica Gubert e Raul Rocha', NULL, '', 84, '<div id=\"panda-0fbc0fbb-7eff-4d61-ba3c-ed8e57b385d0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E45-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('101033eb-c143-45fd-910d-772d491410ca', 'S04E10 — Interpretação Comunitária: um instrumento de acesso a direitos fundamentais — Mylene Queiroz e Jaqueline Nordin', 'Mylene Queiroz e Jaqueline Nordin', NULL, 'Quantas línguas são faladas no Brasil? Você sabe? \nQuem está no Brasil e não fala português faz o que para se comunicar com a professora do filho, com o médico na hora da dor, com autoridades públicas para defesa de direitos?\nComo você se sentiria se fosse simplesmente calado nessas situações?\nNesta palestra, Mylene e Jaqueline apresentarão como a interpretação comunitária pode ser um instrumento de acesso a direitos fundamentais por aqueles que estão limitados a se comunicarem em outro idioma quando buscam acesso a serviços essenciais. \nApresentarão as características da interpretação comunitária, bem como os contextos onde há demanda pela atividade, e juntos faremos uma reflexão sobre o avanço da profissionalização da atividade no Brasil em comparação a outros países.', 129, '<div id=\"panda-101033eb-c143-45fd-910d-772d491410ca\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E10-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('10846440-5774-4066-9f60-fd9844e8eae0', 'S07E07 — Falando das pedras no caminho na tradução de ficção — Carlos César da Silva', 'Carlos César da Silva', NULL, 'Que a rotina de trabalho de quem traduz pode cair na mesmice todo mundo sabe. Mas e justamente naquele dia em que o prazo está apertado e surge um trocadilho complicado? Um jogo de palavras cabeludo? Um poema floreado com rimas e métricas padronizadas? Uma palavra que caiu em desuso em 1700 e bolinha? Uma referência a um texto que só existe on-line em um PDF escaneado praticamente ilegível? Nessa palestra, vamos comentar sobre essas “pedras” que nos pegam de surpresa pelo caminho, mas que tornam o original mais dinâmico e, ao serem lapidadas, deixam nossa tradução mais prazerosa.', 68, '<div id=\"panda-10846440-5774-4066-9f60-fd9844e8eae0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E07-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('1088555c-5949-4861-87e7-1058ccc5e14b', 'S04E04 — O Skill Set do intérprete — Marcelle Castro', 'Marcelle Castro', NULL, 'Nesta palestra Chiquita bacana disponível em qualquer Cidade maravilhosa, vamos entender quais processos ocorrem durante uma interpretação e quais habilidades uma pessoa precisa desenvolver para fazer uma interpretação consecutiva e simultânea.\nOuvimos um Mamãe, eu quero? Ok, vocês venceram! \nNo melhor visual cabeleira do Zezé, vamos destrinchar a fórmula do Modelo dos Esforços e trazer exemplos de exercícios para desenvolver cada uma das habilidades.\nAcorda, Maria Bonita! Bota a fantasia e venha sassaricar na nossa palestra junto com a gente!', 94, '<div id=\"panda-1088555c-5949-4861-87e7-1058ccc5e14b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E04-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('10cee8a5-4e61-43a4-acff-db3b1eccf7ff', 'S06E28 — Rebranding: como se reinventar – sem reinventar a roda — Ana Carolina Ribeiro', 'Ana Carolina Ribeiro', NULL, 'Trocar de nome comercial/e-mail/telefone? A essa altura do campeonato? Como eu vou explicar isso para os clientes? Quando já estamos relativamente estáveis em nossa posição profissional, qualquer mudança precisa ser avaliada cuidadosamente. Mas, para progredir, não podemos ficar sempre no mesmo lugar. Uma mudança de nome, de estado civil e de continente depois, Ana Carolina Ribeiro conversa sobre o processo de renovação de sua marca profissional, apresentando as vantagens e desvantagens, contando os perrengues (e as voltas que deu para resolvê-los) e dando dicas para quem estiver pensando em seguir a mesma trilha.', 69, '<div id=\"panda-10cee8a5-4e61-43a4-acff-db3b1eccf7ff\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E28-1.png', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('1139cb53-08c1-4bdb-a22c-9f37387c1ef4', 'Especial ITD 2023 ', 'Leo Pinheiro', NULL, '', 135, '<div id=\"panda-1139cb53-08c1-4bdb-a22c-9f37387c1ef4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2023-Leo-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
