('29dc3483-a8c4-457f-96c7-4756f2648a42', 'Oficina de HQs ', 'Carol Pimentel', NULL, '', 168, '<div id=\"panda-29dc3483-a8c4-457f-96c7-4756f2648a42\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/OFICINA-Carol-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('2a01e0cc-6d40-4879-8fc0-d4fa898a8628', 'S08E19 — A IA e o futuro da tradução: uma análise do panorama atual e expectativas — Valter Mendes', 'Valter Mendes', NULL, 'Esta palestra analisa o impacto da inteligência artificial (IA) no cenário da tradução, mostrando o panorama atual e as expectativas em relação ao uso da IA na tradução. Serão discutidas as mudanças no mercado de tradução impulsionadas pela tecnologia, e a palestra também vai explorar como a IA está sendo integrada às ferramentas de tradução, automatizando tarefas e abrindo novas oportunidades de especialização.', 85, '<div id=\"panda-2a01e0cc-6d40-4879-8fc0-d4fa898a8628\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E19-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
