('73039ef1-4b9d-4dd7-8857-10431d38feae', 'Quanto vale meu trabalho ', 'William Cassemiro', NULL, 'Palestra de William Cassemiro sobre um método para cálculo de valor a ser cobrado no EMPREENDE LETRAS 2021.', 47, '<div id=\"panda-73039ef1-4b9d-4dd7-8857-10431d38feae\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/William-Qnt-vale_-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('74cc5e90-2619-49b1-b482-6a5fd052822f', 'S08E02 — Manipulando a IA Generativa — Inteligências Artificiais, Perigos Reais — Marcus Mangetti', 'Marcus Mangetti', NULL, '', 87, '<div id=\"panda-74cc5e90-2619-49b1-b482-6a5fd052822f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E02-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('74fdc4e2-4178-4e84-9485-a3619ef62451', 'S04E15 — Perdido ou cantando a caminho do banco? Como anda você na profissão um ano depois do mundo mudar? — Richard Laver', 'Richard Laver', NULL, 'Passado um ano do início de um processo de reversão inesperada de expectativas em todos os níveis, é possível observar um amplo espectro de graus de satisfação profissional entre tradutores e intérpretes.\nEm uma ponta há quem esteja cantando a caminho do banco ou, melhor dizendo, abrindo o app de internet banking com um sorriso de orelha a orelha. Na outra estão aqueles que, ainda perdidos, esperam tudo voltar ao que era antes na esperança de continuar a fazer o que sempre fizeram.\nNesta palestra, Richard Laver abordará sobre este espectro e como tradutores e intérpretes estão se posicionando em um mercado que mudou muito rápido e, portanto, exigiu (e continua exigindo) que quem não quiser ficar para trás se adapte em ritmo acelerado.', 120, '<div id=\"panda-74fdc4e2-4178-4e84-9485-a3619ef62451\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E15-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL);
INSERT INTO `lectures` (`id`, `title`, `speaker`, `speaker_minibio`, `description`, `duration_minutes`, `embed_code`, `thumbnail_url`, `image`, `category`, `tags`, `created_at`, `updated_at`, `is_featured`, `is_live`, `language`, `level`) VALUES
('75cd2b8a-d11b-4d39-a436-9e035f5cb017', 'S03E34 — O fantástico mundo da pesquisa clínica — Kelly Elizeu', 'Kelly Elizeu', NULL, 'A pesquisa clínica é uma área com muita demanda tradutória, mas ainda é um grande mistério para a maioria das pessoas, inclusive os tradutores. Vamos conversar sobre a história e a importância da pesquisa clínica, quais são os aspectos éticos e as regulações que regem os ensaios clínicos atualmente. Traga as suas dúvidas para desmistificar o assunto melhorando, assim, a confiabilidade das fontes de referência terminológica.', 83, '<div id=\"panda-75cd2b8a-d11b-4d39-a436-9e035f5cb017\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E34-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('75e1c43c-6862-4617-998f-6006c412dcf7', 'S03E08 — Tradutores formados, informados e desenformados. Nossos muitos caminhos — Daniel Estill', 'Daniel Estill', NULL, '', 98, '<div id=\"panda-75e1c43c-6862-4617-998f-6006c412dcf7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E08-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7695e26c-dc48-42ce-8370-e853567b7ebf', 'S05E13 — Melhores práticas de LQA: um Fail diz tudo? — Andrea Gonçalves Pinto', 'Andrea Gonçalves Pinto', NULL, '', 101, '<div id=\"panda-7695e26c-dc48-42ce-8370-e853567b7ebf\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E13-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('76b0b8ed-bc4c-45d2-bd87-90cc39a7781b', 'S05E30 — A tradutora roqueira: livros, música e interação com os leitores — Candice Soldatelli', 'Candice Soldatelli', NULL, 'Imagine ser fã de rock desde a pré-adolescência e, anos depois, trocar e-mails com um dos maiores bateristas de todos os tempos para tirar dúvidas sobre tradução? Mais que um sonho realizado, é uma responsabilidade imensa. Nessa palestra, falo sobre como traduzir livros sobre música me aproximou dos meus ídolos, dos fãs das bandas e de todo o universo das gravadoras, da crítica musical, dos shows e, principalmente, do amor pela arte que é a trilha sonora das nossas vidas. Pesquisas, entrevistas, trocas de mensagens, visitas in loco, revisão técnica e a relação próxima com os autores dos livros, revisores e preparadores de originais: todos os passos de uma jornada profissional em busca da melhor tradução possível.', 92, '<div id=\"panda-76b0b8ed-bc4c-45d2-bd87-90cc39a7781b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E30-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7717f6ba-2944-44ce-888c-5c6641e66dcd', 'S07E06 — Audiodescrição de Cinema de Terror — Marcella Wiffler Stefanini', 'Marcella Wiffler Stefanini', NULL, 'Nesta palestra, iremos nos debruçar sobre a audiodescrição (AD) como uma modalidade de tradução audiovisual acessível (TAVA). Sob tal perspectiva, retomaremos alguns postulados da semiótica de Peirce para compreendermos a AD enquanto tradução intersemiótica e, com base nisso, pensarmos possibilidades de AD para o cinema de terror, tanto no que tange ao roteiro como à narração. Nossa reflexão irá partir da análise de alguns exemplos de AD de filmes de terror, bem como da percepção de alguns audiodescritores entrevistados durante minha pesquisa de doutorado e suas estratégias de tradução do terror.', 92, '<div id=\"panda-7717f6ba-2944-44ce-888c-5c6641e66dcd\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E06-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('7784926f-74dc-4847-90f6-9e9ddba691b7', 'S07E11 — Como se preparar para o apocalipse zumbi — Denise Bobadilha', 'Denise Bobadilha', NULL, '', 53, '<div id=\"panda-7784926f-74dc-4847-90f6-9e9ddba691b7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E11-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('78df2dc9-450e-4e84-ae52-ff36c23b4c62', 'Semana intensiva — Carteira qualificada', 'André Ribeiro', NULL, '', 71, '<div id=\"panda-78df2dc9-450e-4e84-ae52-ff36c23b4c62\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Semana-Intensiva-Carteira-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('790de6fe-f8fd-4349-9679-2b8a02379266', 'S05E21 — Variantes linguísticas: com que roupa eu vou? — Danny Reis', 'Danny Reis', NULL, 'O que são registros do idioma? Podemos (e devemos) usar os vários registros da língua da mesma forma que escolhemos as roupas mais adequadas para cada ocasião da vida. Baseando-se em Marcos Bagno, Danny discutirá norma culta, graus de formalidade de um texto e mostrará alguns exemplos dos vários registros usados em cada tipo de texto com que trabalha: TCC, aulas EaD, livros de ficção e não ficção, audiolivros, revistas e produções audiovisuais (dublagem).', 73, '<div id=\"panda-790de6fe-f8fd-4349-9679-2b8a02379266\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E21-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('799b34b6-d7d9-43c2-ab06-a10bd323df84', 'S08E15 — Tradução Médica e ChatGPT: do Prontuário ao Prompt — Luciana Bonancio', 'Luciana Bonancio', NULL, 'Nesta palestra interativa e descontraída, Luciana Bonancio vai mostrar como transformar o ChatGPT em seu assistente de pesquisa na tradução de textos médicos. Vamos do prontuário ao prompt com estratégias para ajudar você a usar a inteligência artificial com segurança, bom senso e criatividade para pesquisar, revisar, adaptar e verificar se um termo realmente existe na língua alvo. Tudo isso com exemplos reais, atividades práticas e dicas de como explorar a inteligência artificial usando sua inteligência humana.', 83, '<div id=\"panda-799b34b6-d7d9-43c2-ab06-a10bd323df84\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E15-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('79e9240e-5aef-491e-a5ca-fae20c513b4a', 'S06E37 — Interpretação de texto e tradução — Natalie Gerhardt', 'Natalie Gerhardt', NULL, 'Nessa palestra, Natalie abordará questões que vão além dos aspectos linguísticos da tradução, tais como a capacidade de interpretação de texto de acordo com o contexto, a sensibilidade de uma leitura mais profunda que leva em conta questões de intenção do autor e identificação de aspectos culturais que trazem mais uma camada para o texto.', 95, '<div id=\"panda-79e9240e-5aef-491e-a5ca-fae20c513b4a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E37-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7a82c6ea-e08d-45c0-af5a-f9b1536f4696', 'T101+Phorte ', 'Ana Julia Perrotti', NULL, '', 73, '<div id=\"panda-7a82c6ea-e08d-45c0-af5a-f9b1536f4696\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101Phorte-2023-Ana-Julia-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('7ace0dd4-073a-465d-9d68-0a899893df7f', 'T101+Quijote ', 'Marcelo Andreoti', NULL, 'Nesse encontro, teremos um diálogo sobre os caminhos que a interpretação está encontrando em um mundo pós-pandemia. O que um mercado dominado por Inteligência Artificial, Internet das Coisas, Aprendizado da Máquinas e tantas novas nomenclaturas como Wearables, B2B, SaaS e muito mais, busca nesses novos profissionais que devem oferecer soluções linguísticas?', 121, '<div id=\"panda-7ace0dd4-073a-465d-9d68-0a899893df7f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101QuijoTe-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('7b2c0104-1cdc-48b9-85b3-ea58236cc1d4', 'S04E49 — FAQ de tradutores sobre finanças e investimentos — Isabela Fontanella', 'Isabela Fontanella', NULL, '“Como organizar as finanças sem salário fixo? Precisa investir todos os meses? Vale a pena fazer previdência privada?” Essas são algumas das dúvidas mais frequentes que tradutores têm sobre dinheiro. A maior parte do conteúdo produzido sobre finanças pessoais fala com assalariados e não com autônomos. Por isso, depois de atender vários tradutores em sua consultoria, Isabela compilou as dúvidas mais frequentes e responderá a todas – sem cerimônias.', 25, '<div id=\"panda-7b2c0104-1cdc-48b9-85b3-ea58236cc1d4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E49-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7b876af7-8c62-4fc9-a63b-58e2a577b14a', 'S06E14 — Que tempo bom, que nunca volta mais — Karina Wuo', 'Karina Wuo', NULL, '', 61, '<div id=\"panda-7b876af7-8c62-4fc9-a63b-58e2a577b14a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E14-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7c8e7bf0-efd6-4f46-8623-41e0a2d8c48d', 'S08E08 — Espelho, espelho na parede? Nem sempre é traduzindo que se traduz — Luiza Levy e Renato R. Geraldes', 'Luiza Levy e Renato R. Geraldes', NULL, '', 62, '<div id=\"panda-7c8e7bf0-efd6-4f46-8623-41e0a2d8c48d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E08-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('7cd6ea68-72c6-40d8-bb91-815f2ae668a2', 'S06E42 — O Papel dos Revisores na Produção de Livros Didáticos — Marianna La Vega', 'Marianna La Vega', NULL, 'Nessa palestra, vamos dar uma olhada nos bastidores da revisão de livros didáticos no Brasil. Vamos falar sobre como esses livros são produzidos, destacando a importância da Base Nacional Comum Curricular (BNCC). Vamos mergulhar nas etapas da revisão, garantindo que o conteúdo seja preciso e apropriado para os estudantes. Também discutiremos como os materiais didáticos têm regras específicas para cada nível de ensino. Por último, vamos abordar a necessidade de representação inclusiva e como entrar nesse campo.', 101, '<div id=\"panda-7cd6ea68-72c6-40d8-bb91-815f2ae668a2\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E42-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('7d45cf2a-f60f-47fd-91f9-fbfc0c280ab8', 'S05E19 — Cadê o original que estava aqui? Quando uma tradutora se torna copywriter — Lara Talhaferro', 'Lara Talhaferro', NULL, 'Na era do acesso instantâneo a infinitas opções de produtos e serviços, saber cativar seu leitor — e possível cliente — é uma estratégia valiosíssima. Criado para motivar a realização de uma ação, o copywriting é uma técnica de escrita de textos persuasivos, que visa aumentar engajamento e vendas. Mas, e quando uma tradutora se torna copywriter? Em que aspectos a formação em Tradução auxilia nessa jornada? Quais habilidades precisam ser desenvolvidas? Nesta palestra, Lara compartilha os aprendizados que levou consigo, os que adquiriu e os que busca enquanto trilha esse novo caminho — que seus colegas tradutores também podem vir a trilhar.', 98, '<div id=\"panda-7d45cf2a-f60f-47fd-91f9-fbfc0c280ab8\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E19-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7e9281bf-f893-4776-9370-2ffedabe3dd8', 'S04E41 — Filhos e Carreira: lições e dicas de tradutores e intérpretes — Luciane Camargo', 'Luciane Camargo', NULL, 'Após duas rodadas de discussões com tradutores e intérpretes – que também são mães e pais, esta palestra de Luciane tem como objetivo trazer os destaques abordados nelas, compilando aprendizados e dicas de como conciliar o trabalho na área de tradução e interpretação com a vida pessoal quando se tem filhos. Pontos muito úteis e relevantes a serem refletidos e levados em consideração para os profissionais que se dividem entre essas duas funções ou mesmo para aqueles que estão entrando neste mercado de trabalho e têm filhos ou que já estão no mercado e serão mães e pais num futuro próximo.', 127, '<div id=\"panda-7e9281bf-f893-4776-9370-2ffedabe3dd8\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E41-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7ec379ed-03fa-4035-9e13-974a95426da5', 'Terças da Cultura V ', 'Isa Mara Lando', NULL, 'Mais uma nova atividade que passa a fazer parte do que oferecemos na Translators101: Terça-feira da Cultura, com Isa Mara Lando! Isa conversará por uma hora sobre duas músicas, um filme e um livro. A ideia é aprimorar nosso repertório cultural.', 123, '<div id=\"panda-7ec379ed-03fa-4035-9e13-974a95426da5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/TERCA-FEIRA-5-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('7f29c262-db00-458f-8e4d-743038262f86', 'S04E42 — Condições que devemos exigir para a interpretação remota — Tony Rosado', 'Tony Rosado', NULL, '', 99, '<div id=\"panda-b417e3b4-baf9-4a94-845c-a6c682f7b76f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E42-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('7f748f7e-8e9b-455a-b6db-cee4f01876f7', 'S07E32 — Gerentes de projetos: os maestros do setor de tradução e localização — Gisley Ferreira', 'Gisley Ferreira', NULL, 'Quem vê um projeto de tradução e localização pronto não imagina quantas etapas seu fluxo de trabalho tem, nem que tipo de profissional faz acontecer isso tudo. O gerente de projetos é a peça-chave que faz funcionar todas as engrenagens de uma empresa de tradução. Que perfil os PjMs têm? Quais são suas responsabilidades? O que eles esperam do relacionamento com os linguistas? Esta palestra mostrará de forma geral o que esse profissional faz e sua importância para os negócios no setor linguístico.', 74, '<div id=\"panda-7f748f7e-8e9b-455a-b6db-cee4f01876f7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E32-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('7fcf3883-8e94-4b7f-bab6-801336b44a6a', 'S04E17 — Mentoring: a ferramenta para conseguir uma carreira em tradução — Ana Saldanha', 'Ana Saldanha', NULL, 'Muitos recém-formados e novatos querem iniciar uma carreira no mundo da tradução profissional e não sabem o que fazer.\nA falta de orientação e de informação proporcionada pelas Instituições de Ensino Superior deixa estes futuros tradutores perdidos e sem perspetivas de futuro profissional.\nO Mentoring é uma ferramenta que, se bem utilizada, consegue colocar os novatos a trabalhar, no entanto, não há poções mágicas e o trabalho árduo é a linha a seguir.', 113, '<div id=\"panda-7fcf3883-8e94-4b7f-bab6-801336b44a6a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E17-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('81279400-beaf-4380-bbc5-eb353c9141ec', 'S06E44 — O gênero neutro está presente. E você, está no Presente ou no passado? — Thiago Hilger', 'Thiago Hilger', NULL, 'Já faz algum tempo que debatemos o uso do gênero neutro na língua portuguesa. A utilização de pronomes, adjetivos e substantivos neutros no dia a dia é crescente, especialmente entre a população mais jovem, que tende a ter menos preconceitos e ser mais aberta à inclusão. Pessoas não-bináries jogam jogos também, assim como você e eu. Para representá-las de forma adequada, eu participei de um projeto de adaptação de um jogo para a linguagem neutra. Nesta palestra, conto em mais detalhes o processo e as técnicas utilizadas para fazer este tão importante trabalho de inclusão.', 65, '<div id=\"panda-81279400-beaf-4380-bbc5-eb353c9141ec\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E44-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('8161ab97-124b-4914-83b8-0c93632b1fe6', 'Semana intensiva — Negociação avançada', 'André Ribeiro', NULL, 'Negociação é um jogo. Entre para vencer. Omitir não é mentir. Não fale tudo. Os diferentes cenários da negociação. Comando da negociação: você e você. O cliente que paga bem e sabe que paga bem (a galinha dos ovos de ouro). Acompanhamento da negociação. Estudos de casos reais.', 111, '<div id=\"panda-8161ab97-124b-4914-83b8-0c93632b1fe6\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Semana-Intensiva-Negociacao-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('865a3d66-7c83-4521-9fe9-df09fea5431c', 'Especial #ITD 2020 — T101 explica SDL Studio', 'Fábio Matias', NULL, 'Conheça o básico da ferramenta SDL Studio.', 57, '<div id=\"panda-865a3d66-7c83-4521-9fe9-df09fea5431c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Fabio-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('86b1951b-50f1-40d8-b223-99b5bf849b86', 'S02E04 — Tradução para dublagem de cinema — Bianca da Costa', 'Bianca da Costa', NULL, '', 67, '<div id=\"panda-86b1951b-50f1-40d8-b223-99b5bf849b86\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E04-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('86bc0649-b038-4846-816d-fd8aa102e85d', 'S07E39 — Legenda automática: a vilã da vez — Andressa Gatto', 'Andressa Gatto', NULL, '', 65, '<div id=\"panda-86bc0649-b038-4846-816d-fd8aa102e85d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E39-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('86f20233-c3e4-4913-8d55-fe4535c8469b', 'S04E01 — Como é que traduz essa porr@? — Evelise Scapol e Renato Geraldes', 'Evelise Scapol e Renato Geraldes', NULL, '', 118, '<div id=\"panda-86f20233-c3e4-4913-8d55-fe4535c8469b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E01-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('87490605-2643-40d4-b8c7-19adf67f8eb5', 'S07E23 — Financeiro é a mãe: a ciência por trás do \'na volta a gente compra\' — Dea Moretto', 'Dea Moretto', NULL, 'Um dos principais desafios do profissional autônomo é a variação da renda mês a mês. O conhecimento de técnicas simples como o fluxo de caixa pode ajudar nas tomadas de decisões sobre seus gastos e investimentos.\nOs participantes da palestra receberão um template prontinho para iniciar sua jornada financeira e decidir se é agora ou é \"na volta\" que a gente compra!', 69, '<div id=\"panda-87490605-2643-40d4-b8c7-19adf67f8eb5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E23-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('87d05499-78be-4f2e-8cba-f837ceb2bf83', 'S04E14 — A importância dos Guias de Estilo na tradução — Roberta Jenkins', 'Roberta Jenkins', NULL, 'Nesta palestra, a especialista em localização, transcriação e LQA Roberta Jenkins conversa sobre o famigerado Guia de Estilo e suas diferentes facetas: histórica, teórica e prática.\nO objetivo é conhecer um pouco mais sobre esse recurso indispensável para tradutores e revisores, não importa o idioma.\nAo final, você saberá como criar um Guia de Estilo efetivo que atenda ao cliente final e às equipes de tradução e de revisão.', 86, '<div id=\"panda-87d05499-78be-4f2e-8cba-f837ceb2bf83\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E14-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('882a5bc6-fe9d-4fc4-8916-6c675fb34fd7', 'S05E41 — Traduzindo marketing — Filipe Alverca', 'Filipe Alverca', NULL, 'Com tantas áreas na tradução, a localização de marketing é mais uma possibilidade de atuação. Além do traquejo linguístico para produzir traduções que soem como se tivessem sido escritas originalmente na língua de destino, quem traduz marketing precisa estar por dentro de conceitos que, além de facilitar o trabalho, ajudarão as marcas a alcançarem seus objetivos. Neste encontro, Filipe abordará conceitos básicos relacionados ao Marketing, tendências na tradução e dicas para afiar a criatividade.', 80, '<div id=\"panda-882a5bc6-fe9d-4fc4-8916-6c675fb34fd7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E41-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('8a558651-76f7-4d96-b37c-9b84499d70d9', 'S04E13 — A importância das ferramentas digitais para a tradução — Valter Mendes Jr.', 'Valter Mendes Jr.', NULL, 'Nesta palestra, Valter Mendes abordará alguns dos motivos que fazem das ferramentas digitais aliadas importantes para tradutores de todas as áreas e especialidades. Será apresentado um panorama geral das MTs e CAT tools (principalmente) e também um pouco sobre outras ferramentas que podem ajudar em nosso ofício.\nAlém disso, Valter tentará responder a algumas perguntas que sempre atormentam quem está começando no assunto, como qual ferramenta escolher e como aprender a usar uma.', 126, '<div id=\"panda-8a558651-76f7-4d96-b37c-9b84499d70d9\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E13-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('8aa06959-9700-4944-9ef1-765b759676cd', 'S07E16 — O novo mercado de tradução: a revolução da inteligência artificial — Aline Tomasuolo', 'Aline Tomasuolo', NULL, 'Há cerca 15 anos, capas de jornais e revistas anunciavam o fim da carreira dos\ntradutores, com o advento e aperfeiçoamento do Google Tradutor. E cá estamos, mais\nfortes do que nunca. O mesmo ocorre agora com o ChatGPT e IA. A tradução\nautomática nos mostrou que a tecnologia pode ser uma aliada valiosa, desde que a\nutilizemos de forma ética e aprimorada. É hora de abraçar essa mudança e aprender a\nsurfar essa onda em vez de lutar contra ela. Nessa palestra, Aline vai abordar os atuais\nusos já possibilitados pela inteligência artificial e apresentar recursos para se manter\natualizado conforme novas tecnologias e ferramentas surgirem.', 82, '<div id=\"panda-8aa06959-9700-4944-9ef1-765b759676cd\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E16-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('8b58e985-8d4f-42ad-9a52-9808731bbf3b', 'S06E26 — Como a dramaturgia influencia a tradução audiovisual — Jacqueline Plaça', 'Jacqueline Plaça', NULL, 'A oferta cada vez mais instigante de filmes, séries e documentários, impulsionada pelas plataformas de streaming, tenta atingir cada vez mais públicos diferentes, em diversos países e idiomas. As equipes de roteiro e direção se esmeram em deixar seus diálogos, personagens e montagem mais cativantes que nunca. No momento da distribuição desses filmes, as equipes de tradução audiovisual têm pouco tempo e informação sobre o material. Nessa palestra, vamos entender a influência da dramaturgia na TAV.', 119, '<div id=\"panda-8b58e985-8d4f-42ad-9a52-9808731bbf3b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E26-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('8cb423b9-5023-4764-82d1-d3c103c28e19', 'Como cobrar uma tradução ', 'William Cassemiro', NULL, '', 40, '<div id=\"panda-8cb423b9-5023-4764-82d1-d3c103c28e19\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/William-Qnt-vale_-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('8d3025ad-dbf0-4ce2-90af-2616dbcbabe7', 'S04E28 — Vivendo da tradução em Portugal — Raissa Duboc', 'Raissa Duboc', NULL, 'Você trabalha ou tem vontade de trabalhar com tradução? Pensa em trabalhar como linguista freelancer fora do país?\nNesta palestra, a legendadora e mestranda Raissa Duboc falará um pouco sobre os vários caminhos que podem nos levar ao ramo da tradução e sobre as possibilidades de morar fora do país, comentando sua experiência e sua mudança do Brasil para Portugal.', 100, '<div id=\"panda-8d3025ad-dbf0-4ce2-90af-2616dbcbabe7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E28-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('8d712fa2-ec7c-444f-bc53-17d012c7b132', 'Dicas: Alongamento ', 'Renata Cassemiro', NULL, '', 1, '<div id=\"panda-8d712fa2-ec7c-444f-bc53-17d012c7b132\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Renata-HR-1920x1080.png', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('8eb80a26-bb66-4a9f-a380-65a909d54c0d', 'S04E11 — Como a tecnologia facilita a vida do tradutor — Rafa Lombardino', 'Rafa Lombardino', NULL, 'Os tradutores não devem depender somente de ferramentas CAT para se posicionarem no mercado. \nCom os avanços tecnológicos das últimas três décadas, hoje podemos ter o nosso escritório virtual para interagir com clientes e colegas de profissão nos quatro cantos do mundo. É também a tecnologia que nos permite ter uma presença on-line, aprimorar os nossos conhecimentos e aumentar a nossa produtividade.\nNesta palestra, vamos falar das várias tecnologias que facilitam a nossa vida profissional e nos permitem alcançar eficiência e coerência no nosso trabalho.', 113, '<div id=\"panda-8eb80a26-bb66-4a9f-a380-65a909d54c0d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E11-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('908883f9-9147-4d8d-9974-85d1b0a96280', 'Especial ITD 2023 ', 'Raphael Corrêa', NULL, '', 153, '<div id=\"panda-908883f9-9147-4d8d-9974-85d1b0a96280\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ESPECIAL-ITD-2023-Raphael-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('91985041-bd30-45c2-9688-af77e01a1a0d', 'Oficina PDI II ', 'Patrícia Loreto e Luciana Bonancio', NULL, '', 74, '<div id=\"panda-91985041-bd30-45c2-9688-af77e01a1a0d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/OFICINA-PDI-2-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('9373566a-9537-40c5-a3cc-6c83b135b468', 'S07E38 — A IA e o mundo da tradução — Sandra Garcia', 'Sandra Garcia', NULL, '', 62, '<div id=\"panda-9373566a-9537-40c5-a3cc-6c83b135b468\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E38-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('9377343f-17a6-4599-8845-46f0e8dc8cac', 'Spin-off_03 ', 'Gabriel Leszczinski', NULL, '', 85, '<div id=\"panda-9377343f-17a6-4599-8845-46f0e8dc8cac\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Spin-off_03-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('9413bcc7-c757-4c92-81d9-36e03b2a11f0', 'Spin-off_08 ', 'Luidg Quitete', NULL, '', 90, '<div id=\"panda-9413bcc7-c757-4c92-81d9-36e03b2a11f0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Spin-off_08-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('9744bfe0-ab7e-11f0-916e-bad1eb27008a', 'S08E33 — TDAH, autismo ou altas habilidades? Então, use seus superpoderes na tradução', 'Jacqueline Plaça', 'Formada em Audiovisual pela USP, pós-graduada em Educação pelo SENAC, viaja constantemente para trabalhos voluntários em projetos sociais pela América Latina. Especialista em roteiro, trabalha com tradução audiovisual há 13 anos, analisando a estrutura dramatúrgica das obras ao elaborar legendas, roteiros de dublagem e audiodescrição. Além disso, se dedica às atividades de interpretação simultânea e consecutiva de espanhol, inglês e português, com foco em eventos de cinema e justiça climática.', 'Neurodivergência, sobrecarga sensorial, perfeccionismo, burnout. Se essas palavras têm povoado seu cotidiano, provavelmente você é uma pessoa neurodivergente, ou suspeita ser, ou é neurotípica convivendo com atípicas. Ser neurodivergente é sinônimo de ter superpoderes muito potentes! Nessa palestra, vamos entender quais são eles, o que fazer para lidar com tanta potência sem ter um esgotamento, e, o melhor, como trabalhar com outras pessoas na tradução e interpretação cultivando a saúde mental. As palavras mágicas são: neuroplasticidade, hiperfoco, menu de dopamina e body doubling. Quer saber como usá-las, meu querido colecionador de palavras? Vem comigo e te conto no caminho.', 92, '<div style=\"position:relative;padding-top:56.25%;\"><iframe id=\"panda-9b6c3409-36bd-4314-a418-b2077b81cee5\" src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174\" style=\"border:none;position:absolute;top:0;left:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"100%\" height=\"100%\" fetchpriority=\"high\"></iframe></div>', '/v/images/thumbnails/S08-HR/thumb_68f2bf26cb7b5.png', '/v/images/thumbnails/S08-HR/lecture_68f27c900d5df.png', 'Geral', '[\"geral\"]', '2025-10-17 17:27:44', '2025-10-17 22:11:50', 1, 0, 'pt-BR', ''),
('97c1499f-28f3-4b98-bbae-0c6833b06755', 'S06E35 — Language Lead? Que bicho é esse? — Mariana Ciocca Alves Passos', 'Mariana Ciocca Alves Passos', NULL, 'A função de Language Lead (especialista em um idioma) existe tanto do lado de quem oferece serviços de tradução quanto de quem compra esses serviços. No entanto, as responsabilidades e expectativas podem ser bem diferentes dependendo de qual lado estamos. Mariana oferece um panorama do que é esperado pelo cliente final e reflete sobre como a experiência em tradução, revisão e teste linguístico a ajudou quando teve a oportunidade de trabalhar nessa função.', 84, '<div id=\"panda-97c1499f-28f3-4b98-bbae-0c6833b06755\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E35-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL);
INSERT INTO `lectures` (`id`, `title`, `speaker`, `speaker_minibio`, `description`, `duration_minutes`, `embed_code`, `thumbnail_url`, `image`, `category`, `tags`, `created_at`, `updated_at`, `is_featured`, `is_live`, `language`, `level`) VALUES
('9838abb7-71e4-4fcc-8125-fb635226f4dc', 'S07E26 — Controle financeiro e relação cliente contador — Luidg Quitete', 'Luidg Quitete', NULL, 'A qualidade das informações recebidas do seu contador depende muito das informações enviadas por você. Nessa palestra vamos abordar as informações que devem ser enviadas por você e de que forma elas devem ser enviadas. Também abordaremos sobre o seu controle financeiro, não basta faturar muito, também precisamos saber se estamos recebendo em dia para organizar os nossos compromissos financeiros. Nem sempre o seu problema está no seu faturamento e sim como você o administra.', 59, '<div id=\"panda-9838abb7-71e4-4fcc-8125-fb635226f4dc\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E26-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('992e56a8-1809-4965-a8df-2c1a5abb7dd1', 'S08E05 — Corpora de Aprendizes de Tradução: Análise e Aplicações — Joacyr Oliveira', 'Joacyr Oliveira', NULL, '', 78, '<div id=\"panda-992e56a8-1809-4965-a8df-2c1a5abb7dd1\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E05-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('994a9333-b2b1-4a56-afbf-ef7b20a2a606', 'Especial #ITD 2020 — Como nasce um dicionário: PED4TI', 'Gilson Mattos', NULL, '', 63, '<div id=\"panda-994a9333-b2b1-4a56-afbf-ef7b20a2a606\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Especial-ITD-2020-Gilson-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('9972c7c3e329e594843303adfa5f3b44', 'Tradução de Rimas em Jogos', 'Lucas Rodrigues Oliveira', NULL, 'A apresentação vai começar abordando a estrutura da poesia, como funcionam as rimas, a métrica, o ritmo e outros elementos que compõem a poesia rimada. Depois, vão ser mostrados vários exemplos de poesias em português para exemplificar esses elementos.\r\nEm seguida, vão ser apresentados exemplos de traduções de poesias (nas duas direções: inglês para português; e português para inglês). No final, o palestrante vai analisar algumas traduções de autoria própria, mostrando como foi o processo criativo.', 0, '', NULL, '/images/lectures/lecture_68d70bd9149ef.png', 'upcoming', NULL, '2025-09-26 21:55:37', '2025-09-26 21:55:37', 1, 0, NULL, NULL),
('9aabe37d-7bf4-48a9-9478-1848b861cd73', 'S02E04 — Treine como um atleta 2: mais dicas para o tradutor autodidata — Isa Mara Lando', 'Isa Mara Lando', NULL, 'Dicas para ampliar seus conhecimentos em línguas e tradução oferecidas por uma das mais renomadas tradutoras brasileiras, Isa Mara Lando.', 54, '<div id=\"panda-9aabe37d-7bf4-48a9-9478-1848b861cd73\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E04-2.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('9ae3d7de-ff8b-4ebb-a2e7-d44591e40274', 'S05E31 — Dicionário Gastronômico: receita e degustação — Rozane Rebechi', 'Rozane Rebechi', NULL, 'Nesta apresentação, Rozane falará sobre a construção do Dicionário Gastronômico. Trata-se de um material terminográfico português < > inglês desenvolvido segundo os princípios da Linguística de Corpus. O objetivo do Dicionário é oferecer aos tradutores e redatores de textos culinários, especialmente de críticas gastronômicas, opções de tradução e exemplos de uso extraídos de textos autênticos, considerando-se as diferenças do gênero entre as duas línguas e culturas. O Dicionário foi testado com tradutores em formação, e os resultados comprovaram que o material auxilia na produção de textos convencionais na língua de chegada. Diante desse resultado positivo, o Dicionário está sendo adaptado para uma termbase.', 108, '<div id=\"panda-9ae3d7de-ff8b-4ebb-a2e7-d44591e40274\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E31-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('9d7162db-af9e-4a00-b475-a213d8adc012', 'S07E37 — Masterclass: Você quer trabalhar na tradução de jogos? — Ivar P. Junior, Horacio Corral e Luciana G. Boldorini', 'Ivar P. Junior, Horacio Corral e Luciana G. Boldorini', NULL, '', 133, '<div id=\"panda-9d7162db-af9e-4a00-b475-a213d8adc012\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E37-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('9e056ee3-8603-4ff0-8136-03eeb8295cf8', 'S05E07 — A comunicação intercultural pelos olhos de uma intérprete de japonês — Anna Ligia Pozzetti', 'Anna Ligia Pozzetti', NULL, 'A profissão do intérprete de conferências demanda estudo constante. A cada evento a terminologia deve ser revista e memorizada em contexto, pois o preparo prévio é um dos maiores aliados para uma interpretação de qualidade. No entanto, existe um outro fator que também tem importante impacto em garantir uma comunicação fluida e correta: a cultura. Conhecer as diferenças culturais entre os países pode ajudar o intérprete e as partes interessadas a se fazerem entender, seja em uma palestra ou em uma negociação comercial. A partir do ponto de vista de uma intérprete de japonês, vamos mergulhar no universo da comunicação intercultural enquanto falamos sobre as peculiaridades que envolvem o idioma e a cultura japonesa.', 86, '<div id=\"panda-9e056ee3-8603-4ff0-8136-03eeb8295cf8\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E07-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('9f29c0c6-46ea-4126-94f1-edfba778c6d7', 'S07E48 — Gerente de projetos de tradução como perspectiva de carreira: mercado, funções e habilidades — Carolina Bisson', 'Carolina Bisson', NULL, '', 84, '<div id=\"panda-9f29c0c6-46ea-4126-94f1-edfba778c6d7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E48-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('9f7fa669-955c-466e-8a8f-5d81278f3585', 'Especial #ITD 2020 — Mais organização e produtividade: Tecnologia é a resposta!', 'Fernanda Rocha', NULL, 'Você consegue imaginar sua vida profissional sem todos os recursos tecnológicos que utilizamos hoje em dia? Aposto que não! Mas até que ponto você realmente tira proveito de tudo o que a tecnologia tem a lhe oferecer? Pois é... Foi pensando nisso que esta palestra “nasceu”.\nAqui, nós vamos explorar seu sistema operacional, dicas de pesquisa, pdfs, contagem de palavras, tags, gerenciamento administrativo e administração de tempo, listando ferramentas e abordagens que vão melhorar sua organização, produtividade e qualidade de vida de uma maneira prática e econômica. ', 87, '<div id=\"panda-9f7fa669-955c-466e-8a8f-5d81278f3585\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Fernanda-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('9fd814b7-ee67-4395-a99f-b8ad14ba15c0', 'S03E33 — Traduzindo jogos de tabuleiro — Juliana Gallo', 'Juliana Gallo', NULL, 'Conheça os bastidores do mundo da tradução dos jogos de tabuleiro. Nesta palestra, vou compartilhar minha experiência na área e mostrar como é o processo de tradução de um jogo, incluindo os desafios, curiosidades e particularidades.', 62, '<div id=\"panda-9fd814b7-ee67-4395-a99f-b8ad14ba15c0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E33-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a27c5067-820e-4cc6-9208-d30cd33d86e3', 'S04E47 — Langue x Parole: uma discussão dicotômica “nesSAUSSUREa” — Lia Bittencourt', 'Lia Bittencourt', NULL, '', 100, '<div id=\"panda-a27c5067-820e-4cc6-9208-d30cd33d86e3\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E47-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a2936cbc-8e78-440b-bb84-34b1272670eb', 'S04E09 — Linguística e Tradução: entre tapas e beijos — Meritxell Almarza', 'Meritxell Almarza', NULL, 'A relação entre a Linguística e a Tradução nem sempre foi tranquila no Ocidente, não é mesmo?\nA Tradução já foi considerada uma simples ferramenta pela Linguística e, por sua vez, a Tradução já considerou desnecessária a Linguística para sua existência e estudo.\nNesta palestra, Meritxell abordará sobre a convivência das duas disciplinas ao longo do tempo e a importância de cada uma para a outra.', 112, '<div id=\"panda-a2936cbc-8e78-440b-bb84-34b1272670eb\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E09-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a2d37999-a2a5-4fa1-930c-d0fe3039f999', 'S02E02 — Aposte no visual! — Carolina Walliter', 'Carolina Walliter', NULL, '', 59, '<div style=\'padding:56.25% 0 0 0;position:relative;\'><iframe src=\'https://player.videodelivery.net/a2d37999-a2a5-4fa1-930c-d0fe3039f999?preload=true&poster=https%3A%2F%2Fvideodelivery.net%2Fa2d37999-a2a5-4fa1-930c-d0fe3039f999%2Fthumbnails%2Fthumbnail.jpg%3Ftime%3D%26height%3D600\' style=\'border:none;position:absolute;top:0;left:0;height:100%;width:100%;\' allow=\'accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture;\' allowfullscreen=\'true\'></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E02-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a3052a55-fc96-4257-a38e-18d72da9944e', 'Respiração consciente ', 'Sofia Pulici', NULL, 'Como anda sua respiração enquanto trabalha? O terceiro encontro de bem-estar será uma sessão de respiração consciente. Vamos falar um pouco sobre a importância de estar ciente da respiração e fazer três exercícios para nos ajudar no dia a dia. Serão exercícios de respiração que podem ser feitos na cadeira de trabalho e que você poderá fazer sozinho/sozinha mesmo após a sessão.', 38, '<div id=\"panda-a3052a55-fc96-4257-a38e-18d72da9944e\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/RESPIRACAO-CONSCIENTE-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('a382b3d6-9750-4511-9ef2-2d13030c44b3', 'Ioga — Cuidados com face, ombros, braços e mãos cadeira', 'Mariana Paz', NULL, 'Cuidados com face, ombros, braços e mãos cadeira com Mari Paz.', 30, '<div id=\"panda-a382b3d6-9750-4511-9ef2-2d13030c44b3\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/MARIANA-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('a3fdc7b2-598f-4118-b022-3b6513565b87', 'S05E15 — Os desafios na tradução de Uma mulher estranha, da escritora feminista turca Leylâ Erbil — Marco S. de Pinto', 'Marco S. de Pinto', NULL, '', 83, '<div id=\"panda-a3fdc7b2-598f-4118-b022-3b6513565b87\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E15-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a42b3f84-fa35-473e-8c00-360e0c9d9b17', 'Spin-off_01 ', 'Equipe da Sociedade Brasileira de Dublagem', NULL, '', 171, '<div id=\"panda-a42b3f84-fa35-473e-8c00-360e0c9d9b17\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Spin-off_01-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('a4bdd90f-d012-4f91-8407-12d4fc391e01', 'Spin-off_05 ', 'Luciana Bonancio', NULL, '', 130, '<div id=\"panda-a4bdd90f-d012-4f91-8407-12d4fc391e01\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Spin-off_05-HR.webp-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('a4f42cb3-a234-11f0-916e-bad1eb27008a', 'S08E23 — Traduzir poesia: uma breve introdução', 'Pedro Mohallem', 'Pedro Mohallem, 29, é poeta, professor e tradutor de poesia. Mestre em Estudos da Tradução pela USP. Seus trabalhos de tradução incluem A Revolução dos Bichos, de George Orwell, e O Mercador de Veneza, de William Shakespeare, ambos pela editora Sétimo Selo, e Sol dos Insones, antologia poética de Lord Byron traduzida a seis mãos com Leonardo Antunes e Bruno Palavro e publicada pela editora Zouk. De poesia autoral, publicou Véspera; Debris, semifinalista do prêmio Oceanos de Literatura em 2020', 'É possível traduzir poesia? Por mais que grandes autores, como Vladimir Nabokov e Robert Frost digam o contrário, é perfeitamente possível. Partindo de uma exposição teórica e de estudos de caso, apresentarei brevemente alguns dos conceitos envolvidos no processo de tradução de poesia para o português: da identificação de sua poeticidade às possíveis abordagens tradutórias, dos rudimentos da versificação à prosódia comparada.', 138, '<div style=\"position:relative;padding-top:56.25%;\"><iframe id=\"panda-a0bfb918-655e-412f-b96a-6b86ec470dc7\" src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174\" style=\"border:none;position:absolute;top:0;left:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"100%\" height=\"100%\" fetchpriority=\"high\"></iframe></div>', '/v/images/thumbnails/S08-HR/thumb_68e2e72b60f00.png', '', 'Literária', '[\"literária\"]', '2025-10-05 21:45:43', '2025-10-05 21:46:19', 1, 0, 'pt-BR', ''),
('a5192b87-6d76-4e75-b67b-a694121a4a8c', 'Maratona — Transcriação', 'André Ribeiro', NULL, '', 93, '<div id=\"panda-a5192b87-6d76-4e75-b67b-a694121a4a8c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Maratona-Transcriacao-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('a66730d6-1638-4da9-ae68-9d8ed9e54c82', 'S06E41 — Driblando a sociedade do cansaço — Francine Oliveira', 'Francine Oliveira', NULL, 'Você já se sentiu à beira de um burnout? Ou melhor: quantas vezes você já se sentiu à beira de um burnout? Decidi reformular minha pergunta porque me dei conta de que o esgotamento parece ter se tornado algo recorrente em conversas com muitos colegas. O filósofo Byung-Chul Han aponta que vivemos na “Sociedade do Cansaço”, em doenças e transtornos da mente são componentes da “paisagem patológica do começo do século XXI”. Ainda assim, descrever-se como workaholic continua a ser uma qualidade e coaches ainda repetem frases de impacto que nos incitam a “trabalhar enquanto eles dormem”. Então, quando descansamos?', 86, '<div id=\"panda-a66730d6-1638-4da9-ae68-9d8ed9e54c82\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E41-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('a6c3f570-6715-4acc-a359-17dded1e7296', 'S04E46 — Italiano e português: tão parecidos e tão diferentes — Mauro Moser', 'Mauro Moser', NULL, 'Ah, o italiano é fácil, é bem próximo ao português, né? É, mas nem sempre! Esta palestra vai fazer com que você evite perrengues, saias justas e constrangimentos.\nO prato principal serão falsos cognatos e situações comunicativas que você precisa ter em mente na hora de falar com um italiano ou traduzir do italiano. Inclusive, o que significa “prato” em italiano?\nSerá uma palestra descontraída, aliás, \"palestra\"? Opa, mais um falso cognato. Quer saber mais sobre esse termo e muitos outros?', 75, '<div id=\"panda-a6c3f570-6715-4acc-a359-17dded1e7296\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E46-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('a6db751f-d3ba-476a-a245-0cc0e13f00ea', 'S03E43 — Os desafios da produção editorial de best-sellers — Suelen Lopes', 'Suelen Lopes', NULL, 'Até chegar à casa dos leitores, os livros estrangeiros passam por uma longa jornada, envolvendo diversos profissionais e departamentos. Como é o processo de tradução e edição de best-sellers? Que desafios o editor precisa enfrentar para realizar um lançamento simultâneo? Por que nem sempre é possível atender a essa demanda? Nessa verdadeira montanha-russa editorial, é de suma importância debater essas questões e repensar as estratégias de produção que levam determinados livros às listas de mais vendidos.', 116, '<div id=\"panda-a6db751f-d3ba-476a-a245-0cc0e13f00ea\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E43-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('aa7bffad-d4c9-49bf-80be-0b87a13fd1c9', 'S03E38 — Tradução automática na tradução técnica: testamos uma abordagem — Carolina Bisson', 'Carolina Bisson', NULL, '', 81, '<div id=\"panda-aa7bffad-d4c9-49bf-80be-0b87a13fd1c9\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E38-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('aabc3cdb-d076-4b1a-a460-b8179515fc57', 'S07E50 — Gramática não é tudo, mas é inescapável — William Cruz', 'William Cruz', NULL, '', 84, '<div id=\"panda-aabc3cdb-d076-4b1a-a460-b8179515fc57\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E50-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('ab2e3c8f-fc2f-4e3e-be23-b146cb4ab2f0', 'S06E30 — Comunicação Acessível: Estratégias para integrar a acessibilidade a teatro, redes sociais, palestras e outras formas de diálogo — Fernanda Brahemcha', 'Fernanda Brahemcha', NULL, 'Como estratégias de verbalização e de reorganização das informações podem nos ajudar a compor uma comunicação mais acessível, que comunique também às pessoas com deficiência visual? Nessa palestra vamos refletir um pouco sobre como estruturamos a nossa comunicação em múltiplas vias, e como somar essas vias para emitir mensagens de forma mais acessível, passando pela audiodescrição como recurso, mas dando foco às ferramentas textuais que podem ser aprendidas a partir dela e além dela, e que podem ser aplicadas por todas as pessoas em contextos variados.', 108, '<div id=\"panda-ab2e3c8f-fc2f-4e3e-be23-b146cb4ab2f0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E30-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ad3ce107-f2bf-4c27-89cc-09a3c9be1c72', 'Dicas: Monitor ', 'Renata Cassemiro', NULL, '', 1, '<div id=\"panda-ad3ce107-f2bf-4c27-89cc-09a3c9be1c72\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Renata-HR-1920x1080.png', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('aff7c429-c2f1-43a0-8880-c5d6356bd205', 'S04E02 — Kit de sobrevivência: Vinte dicas pra se manter na tradução — Andressa Gatto', 'Andressa Gatto', NULL, 'A palestra é um convite para refletir de forma bem sincera sobre vinte ferramentas úteis que profissionais da área de Tradução devem ter, desenvolver e prestar atenção não só para entrarem no mercado, como também para se manterem nele, a despeito de tantas dificuldades que enfrentamos ao longo do caminho.', 106, '<div id=\"panda-aff7c429-c2f1-43a0-8880-c5d6356bd205\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E02-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('affc0a94-102c-4c14-bd9b-ef7288765d14', 'S01E01 — Small step or giant leap?', 'Ulisses Wehby de Carvalho', 'Ulisses é Intérprete de Conferência com 25 anos de experiência. Professor de tradução simultânea. CV completo em www.teclasap.com.br/cv', 'Ulisses traz uma visão realista e bem-humorada sobre a carreira de intérprete de conferência. Ele explica as diferenças entre tradução escrita e simultânea, os requisitos de formação, as exigências do mercado e as situações inusitadas da cabine. Ulisses mostra que o intérprete precisa de desapego, preparo para temas variados (de química a futebol), jogo de cintura para lidar com piadas e sotaques, além de se adaptar às tendências tecnológicas e às condições de trabalho. Uma palestra essencial para quem quer entender os bastidores e as oportunidades da interpretação profissional.', 54, '<div id=\"panda-affc0a94-102c-4c14-bd9b-ef7288765d14\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\">\r\n    <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe>\r\n</div>', 'https://translators101.com/images/thumbnails/S01-HR/S01E01-3.jpeg', NULL, 'Interpretação', '[\"interpreta\\u00e7\\u00e3o\"]', '2025-06-03 21:49:37', '2025-06-07 21:35:20', 0, 0, NULL, NULL),
('b01cff37-016b-4eca-b5ba-f184f1a4db87', 'S02E03 — Assim diz a legenda — Luiz Fernando Alves', 'Luiz Fernando Alves', NULL, 'Palestra de Luiz Fernando Alves', 72, '<div id=\"panda-032f60c9-7ee5-4f5b-9fe8-ec9a589eae27\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E03-3.jpeg', NULL, 'TAV', '[\"tav\"]', '2025-06-10 14:56:57', '2025-06-11 19:03:24', 0, 0, NULL, NULL),
('b09f7ab5-f239-44d2-b39f-4045ca00e522', 'S04E45 — Conhecimento é poder — Natalie Gerhardt', 'Natalie Gerhardt', NULL, 'Conhecer o caminho que o livro percorre desde a sua contratação pela editora até chegar ao leitor pode ajudar os tradutores a ter uma melhor compreensão do impacto de cada decisão tomada pelo editor.\nNessa palestra, Natalie pretende apresentar e descrever os principais processos editoriais pelos quais o livro passa para mostrar como a qualidade do trabalho e a pontualidade da entrega impactam o cronograma.\nTambém abordará como costuma ser feita a seleção de profissionais autônomos que prestam serviços editoriais. Além de apresentar o relatório de tradução que criou como uma ferramenta para preservar suas escolhas, facilitar o trabalho das etapas posteriores e ajudar o editor ou editora a tomar a melhor decisão para a obra.', 64, '<div id=\"panda-b09f7ab5-f239-44d2-b39f-4045ca00e522\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E45-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b126953b-389d-471f-b42a-8d384d6d8e36', 'S06E06 — MINHA nenhuma tradução é perfeita. Como aprender com a preparação de texto — Jana Bianchi e Fernanda', 'Jana Bianchi e Fernanda', NULL, '', 89, '<div id=\"panda-b126953b-389d-471f-b42a-8d384d6d8e36\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E06-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b19b35bb-2105-49fb-ae16-3cf61aed7990', 'S04E35 — Translation and Interpreting in the USA — David Rumsey', 'David Rumsey', NULL, 'Translation and Interpreting in the USA This session will provide an overview of the translation and interpreting industry in the United States.', 93, '<div id=\"panda-b19b35bb-2105-49fb-ae16-3cf61aed7990\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E35-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b1a9b4ad-4d22-4668-a74d-7a3f2c962eaf', 'S07E31 — TRADUSA 2024: Tudo sobre o V Encontro Brasileiro de Tradutores Especializados na Área da Saúde — Ana Julia Perrotti-Garcia, Cátia Santana e Patrícia Gimenez', 'Ana Julia Perrotti-Garcia, Cátia Santana e Patrícia Gimenez', NULL, 'Junte-se a nós para uma live exclusiva onde vamos explicar tudo sobre o TRADUSA 2024 – V Encontro Brasileiro de Tradutores Especializados na Área da Saúde! Saiba mais sobre o evento, conheça a programação completa e tire suas dúvidas ao vivo! Não perca essa oportunidade de se conectar com profissionais da área e se preparar para o maior evento de tradução médica do Brasil.', 55, '<div id=\"panda-b1a9b4ad-4d22-4668-a74d-7a3f2c962eaf\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E31-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b29a0f8c-e47a-4165-9045-5ca9d8296a92', 'S03E42 — Tradutores euprendedores e o relacionamento com o cliente — Rane Souza', 'Rane Souza', NULL, 'Ser tradutor e/ou intérprete exige habilidades quase-ninjas! Você tem que cuidar do marketing, dos impostos, das CAT Tools, dos prazos, da manutenção do seu computador, da licença do Office, da cadeira adequada, de um bom teclado, da visão, da postura, de atualizar seu CV... Ufa! Não é pouco. E veja que só citamos os pontos mais óbvios. Rane Souza, intérprete e tradutora, falará sobre tudo isso e muito mais nessa palestra sobre as pessoas EUpreendedoras.', 123, '<div id=\"panda-b29a0f8c-e47a-4165-9045-5ca9d8296a92\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E42-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b2c7c992-987f-11f0-916e-bad1eb27008a', 'S08E14 — Cuidando da Voz: A Ferramenta Essencial do Intérprete', 'Luiza Brahemcha', '', 'A palestra aborda a importância da saúde vocal para tradutores-intérpretes, destacando cuidados essenciais para preservar a qualidade da voz. Serão discutidos fatores de risco, como uso excessivo da voz, ambiente inadequado e tensão muscular, além de hábitos saudáveis, como hidratação, pausas vocais e aquecimento. Também serão apresentados exercícios práticos para projeção e respiração, ajudando na resistência vocal. O objetivo é fornecer orientações para evitar fadiga, manter a clareza na comunicação e garantir longevidade profissional. Ao final, os participantes terão dicas aplicáveis no dia a dia e entenderão quando buscar acompanhamento especializado.', 91, '<div style=\"position:relative;padding-top:56.25%;\"><iframe id=\"panda-659d4ac3-0fa5-4277-a062-13d854b397bb\" src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174\" style=\"border:none;position:absolute;top:0;left:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"100%\" height=\"100%\" fetchpriority=\"high\"></iframe></div>', '/images/thumbnails/thumb_68e004815ea94.jpeg', '/images/lectures/lecture_68d29dfb9701a.jpeg', 'Interpretação', '[\"ferramentas\"]', '2025-09-23 13:17:47', '2025-10-03 17:14:41', 1, 0, 'pt-BR', ''),
('b3c8b788-beb6-4c45-bc09-0935f351eb57', 'S06E16 — A interpretação consecutiva e outras práticas que te tornam um melhor intérprete de simultânea — Luana Carvalho', 'Luana Carvalho', NULL, 'Essa palestra apresenta um viés pedagógico para conscientizar o intérprete que a prática recorrente de atividades diversificadas é o que aprimora as competências necessárias para exercer a profissão.', 74, '<div id=\"panda-b3c8b788-beb6-4c45-bc09-0935f351eb57\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E16-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b4adfa49-5d16-4141-b469-239c5bff4a3d', 'S06E40 — A importância da inteligência emocional na rotina do profissional autônomo — Shirlei Fernandes Correa', 'Shirlei Fernandes Correa', NULL, 'Partindo dos desafios, inseguranças, medos e dores que grande parte dos profissionais autônomos precisam lidar no cotidiano da profissão, é muito pertinente trazer conceitos da Inteligência emocional. A inteligência emocional sendo desenvolvida diariamente, pode trazer benefícios imensuráveis na forma que o indivíduo vai lidar com os problemas, estresse e decisões do dia a dia, trazendo a possibilidade de reações mais assertivas, interna e externamente.\nO intuito dessa palestra é mostrar aos ouvintes que apesar de todos os pontos de conflito é necessário olhar para si e aprender a identificar sensações e sentimentos que podem estar travando a busca pelo sucesso.', 91, '<div id=\"panda-b4adfa49-5d16-4141-b469-239c5bff4a3d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E40-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b55a5079-b474-4d4d-988a-1179869edc50', 'S04E03 — Linguagem inclusiva: gênero, política e linguagem — Ana Elisa Ribeiro', 'Ana Elisa Ribeiro', NULL, 'Desde a escola básica, aprendemos que, em português, masculino e feminino podem ser expressos pelo \"neutro\" masculino. A premissa é a de que estaremos todos e todas contemplados, subsumidos pelo \"o\" e, em tese, satisfeitos. No entanto, há algum tempo vem se desenvolvendo intenso debate sobre questões de gênero que devem ser de fato contempladas pela linguagem, expressando e incluindo o que não é entendido por todos como automático e nem satisfaz a todas as pessoas. Nesta palestra, abordaremos essas questões, contando um pouco das razões e da história desse debate, além de fornecer exemplos de soluções oferecidas por diversos grupos para a \"linguagem inclusiva\'\'.', 119, '<div id=\"panda-b55a5079-b474-4d4d-988a-1179869edc50\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E03-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b5cd1ce0-d9c7-415f-95bb-7b5186da7991', 'Spin-off_10 ', 'Isa Mara Lando', NULL, '', 134, '<div id=\"panda-b5cd1ce0-d9c7-415f-95bb-7b5186da7991\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Spin-off_10-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('b5f50600-3555-41ec-add4-96dfc52431b5', 'S08E18 — Tradução Audiovisual: Workflow da demanda à entrega — Bruna Andrade', 'Bruna Andrade', NULL, 'Um panorama prático da tradução audiovisual no mercado profissional, com foco em legendagem e dublagem. A partir da experiência em grandes fluxos de mídia, serão abordadas as etapas que envolvem aquisição de conteúdos, avaliação técnica de materiais, processos de tradução, revisão, uso de glossários, ferramentas de apoio e desafios atuais, incluindo testes com IA. A proposta é mostrar como a tradução se integra ao ciclo completo de entrega de um conteúdo — do licenciamento à exibição — e destacar o papel estratégico do tradutor como mediador cultural e guardião da qualidade linguística.', 88, '<div id=\"panda-b5f50600-3555-41ec-add4-96dfc52431b5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E18-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b6585570-56c5-4ce1-b977-752ba8596c97', 'Spin-off_11b ', 'Petê Rissatti', NULL, '', 204, '<div id=\"panda-b6585570-56c5-4ce1-b977-752ba8596c97\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('b669d1a5-32ec-402b-9894-6ffd0735d7fe', 'S05E35 — A Tradulação de Krazy Kat e Otros Kuadrinhos Komplicados (sic) — Érico Assis', 'Érico Assis', NULL, 'Um relato e uma conversa sobre a tradução de Krazy Kat: 1916-1918, de George Herriman, e outras experiências na tradução de quadrinhos.', 75, '<div id=\"panda-b669d1a5-32ec-402b-9894-6ffd0735d7fe\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E35-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b779d178-6e5a-4002-b2ff-2db6a06a6644', 'S07E21 — Ask Me Anything about Interpretainment — Maria Paula Carvalho', 'Maria Paula Carvalho', NULL, 'Você sabe o que é interpretainment? Que tal perguntar tudo o que quiser sobre o tema para Maria Paula Carvalho nesse bate-papo exclusivo da Translators101 com a intérprete que colocou a “periquita da Madonna” nos trend topics?', 72, '<div id=\"panda-b779d178-6e5a-4002-b2ff-2db6a06a6644\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E21-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b7908e7b-2e41-404e-9616-e12eb057d18c', 'S05E17 — Equipamentos e RSI: o que fazer, o que não fazer, quando chorar — Daniel Maciel', 'Daniel Maciel', NULL, 'Nesta palestra, Daniel Maciel dará um apanhado de algumas das boas práticas, das más práticas e das concepções errôneas que se consolidaram ao longo destes duzentos e vinte e seis anos desde o início da pandemia.', 90, '<div id=\"panda-b7908e7b-2e41-404e-9616-e12eb057d18c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E17-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL);
INSERT INTO `lectures` (`id`, `title`, `speaker`, `speaker_minibio`, `description`, `duration_minutes`, `embed_code`, `thumbnail_url`, `image`, `category`, `tags`, `created_at`, `updated_at`, `is_featured`, `is_live`, `language`, `level`) VALUES
('b7b22ea3-63ac-4156-b0d1-c8462aa4b0b9', 'S07E18 — A cabeça do tradutor de russo – O processo de tradução de um clássico da ficção científica. — Robson Ortlibas', 'Robson Ortlibas', NULL, 'Nesta apresentação, Robson Ortlibas discutirá sua tradução de \"A cabeça do professor Dowell\", de Aleksandr Beliáev, lançado pela Tacet Books. Revelará o meticuloso processo de seleção das ilustrações e dos textos complementares, bem como os detalhes envolvidos na escrita da biografia do autor. Abordará os principais desafios enfrentados durante a tradução, destacando as escolhas e as soluções adotadas para manter a autenticidade da obra. A apresentação oferecerá uma visão profunda sobre as complexidades de traduzir um clássico da literatura russa, ilustrando o compromisso necessário para preservar o impacto original do texto.', 125, '<div id=\"panda-b7b22ea3-63ac-4156-b0d1-c8462aa4b0b9\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E18-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b7c8328c-0cf9-4652-bfb6-512a94824b05', 'S07E25 — Caminhos da Tradução na graduação em Letras — Mirella Nunes Giracca e Silvana Ayub Polchlopek', 'Mirella Nunes Giracca e Silvana Ayub Polchlopek', NULL, 'No contexto de cursos de licenciatura, a pesquisa tem importância singular. Se o licenciando sabe como desenvolver essa prática, as chances de levá-la para sala de aula são maiores e mais produtivas. Motivar a pesquisa nas novas gerações determina a diferença entre andar simplesmente e caminhar. Para os Estudos da Tradução, pesquisar define esse caminhar e representa todo um contexto histórico, social, cultural, político, ideológico que atravessa todos os segmentos nos quais o ato tradutório se desdobra. Práticas de pesquisa recentes, na graduação em Letras, têm mostrado que pesquisar tradução é necessário e viável, possibilitando novos olhares para a linguagem.', 129, '<div id=\"panda-b7c8328c-0cf9-4652-bfb6-512a94824b05\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E25-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('b841d2ec-7025-47a8-a5a6-3e6f2a3b5232', 'S03E21 — Como conciliar as carreiras de tradutor e intérprete — Marsel de Souza', 'Marsel de Souza', NULL, 'Tradução e interpretação são ofícios irmãos. Os atributos básicos para a prática de um são também essenciais para o outro. Mas por que tantos profissionais encaram como caminhos distintos? É possível conciliar as duas carreiras? Para responder a essas perguntas, serão abordados aspectos relacionados a mentalidade, preparação/qualificação, práticas profissionais e posicionamento comercial. Vamos falar sobre o que fazer e o que não fazer nessa jornada pelas duas profissões. Ao final, teremos um espaço para a troca de ideias com quem já trilha os dois caminhos e/ou deseja trilhar.', 133, '<div id=\"panda-b841d2ec-7025-47a8-a5a6-3e6f2a3b5232\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E21-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b8d1bd4d-0792-4d51-a01d-d69c7fc3fd9d', 'S04E43 — Como sua mãe já dizia: você não é todo mundo — Regiane Winarski', 'Regiane Winarski', NULL, 'Num mercado pequeno e competitivo, de que forma podemos nos destacar? A prática demonstra que são as pequenas coisas que fazem uma grande diferença.\nNessa palestra, vamos ver com Regiane Winarski algumas dessas pequenas coisas que podem ajudar a dar destaque a um tradutor de livros.\nDiscutirão aspectos como texto, pesquisas, contato com as editoras, como praticar para estar mais preparado para o seu primeiro teste e como apurar seu olhar para a sua própria tradução. O objetivo não é esmiuçar detalhadamente cada um desses tópicos, mas fazer uma passagem abrangente e informativa para que cada um consiga encontrar seu caminho.', 90, '<div id=\"panda-b8d1bd4d-0792-4d51-a01d-d69c7fc3fd9d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E43-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b97fe147-7807-48ed-9644-f8e824f1adae', 'S03E45 — Legendagem especializada: foco no gênero institucional — Carol Alfaro', 'Carol Alfaro', NULL, 'Esta palestra traz reflexões e informações mais específicas sobre o gênero institucional da tradução audiovisual, aquela que é realizada para empresas de diversos ramos e se destina a ensino ou treinamento, promoção, vendas e afins. O que diferencia esse gênero da tradução audiovisual destinada ao entretenimento, tanto em termos do conteúdo quanto do projeto de trabalho e a relação com o cliente? Quais são as características mais adequadas do profissional de tradução para ter sucesso neste campo?', 81, '<div id=\"panda-b97fe147-7807-48ed-9644-f8e824f1adae\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E45-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('b9e298ef-a094-11f0-916e-bad1eb27008a', 'S08E26 — Prospecção no mercado editorial', 'Vanessa Thiago', '', '', 108, '<div style=\"position:relative;padding-top:56.25%;\"><iframe id=\"panda-5dcfba36-dd83-45fa-acb5-9aaf288ea066\" src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174\" style=\"border:none;position:absolute;top:0;left:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"100%\" height=\"100%\" fetchpriority=\"high\"></iframe></div>', '/v/images/thumbnails/S08-HR/thumb_68e02d818a122.png', '/v/images/thumbnails/S08-HR/lecture_68e02d3c41ffc.png', 'Literária', '[\"literária\"]', '2025-10-03 20:08:28', '2025-10-03 20:11:35', 1, 0, 'pt-BR', ''),
('ba558df8-c28f-4b0b-abe5-a653e0685851', 'S07E03 — De férias com o tradutor: Os desafios da tradução de reality shows — Will Xavier', 'Will Xavier', NULL, 'Alguns dos maiores “vilões” para quem traduz na área audiovisual, seja para dublagem ou legendagem, são os reality shows. Nesta palestra, vamos ver quais os principais aspectos dessa modalidade de programa, algumas estratégias úteis para melhorar a qualidade da tradução e por que os reality shows são considerados uma escola para quem trabalha com tradução audiovisual. Vamos analisar alguns trechos de programas que já estão no ar e descobrir que traduzir reality shows pode ser muito divertido.', 97, '<div id=\"panda-ba558df8-c28f-4b0b-abe5-a653e0685851\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E03-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('bb2da225-d299-43eb-b80d-f74a4bd740e9', 'Spin-off_20 I ', 'Reginaldo Francisco', NULL, '', 144, '<div id=\"panda-bb2da225-d299-43eb-b80d-f74a4bd740e9\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('bb368f3c-1f92-4b5f-8966-23deb6195541', 'S07E43 — A sutil arte de gerenciar o seu estresse — Giovana Boselli', 'Giovana Boselli', NULL, '', 124, '<div id=\"panda-bb368f3c-1f92-4b5f-8966-23deb6195541\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E43-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('bb37cb58-f573-4aee-a1e1-32ba033f4430', 'Especial #ITD 2020 — O mundo não te odeia', 'Kelly Elizeu', NULL, '“Recebi um feedback negativo. Perdi o cliente?” “O revisor está trocando seis por meia dúzia só para mostrar trabalho?” “Estou revisando um texto que tem muitos problemas. O tradutor quer que eu faça o trabalho dele?” Essas são algumas das perguntas que passam pela cabeça de todo profissional quando precisa dar ou responder a um feedback negativo. Vamos juntos encontrar soluções para melhorar a qualidade do trabalho do tradutor e do revisor, reduzir o estresse e fidelizar o cliente com atitudes profissionais e respeitosas.', 49, '<div id=\"panda-bb37cb58-f573-4aee-a1e1-32ba033f4430\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Especial-ITD-2020-Kelly-HR-1-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('bb572dab-acb6-47ee-9feb-25e322690258', 'S04E30 — A legendagem na publicidade: particularidades e novas tendências — Dafne Baddini', 'Dafne Baddini', NULL, 'Cada vez mais a Tradução Audiovisual (ou TAV) vem se sub-ramificando, levando o tradutor a ter de atentar para diferentes preferências e padrões de qualidade. Na área da publicidade e do marketing, não é diferente.\nNesta palestra, vamos debater com Dafne algumas particularidades do setor e repensar a legendagem sob uma ótica multimodal, à luz das ideias de Kress e Van Leeuwen.\nTambém apontaremos possíveis tendências e caminhos para garantir acessibilidade de forma atraente a esse mercado.', 74, '<div id=\"panda-bb572dab-acb6-47ee-9feb-25e322690258\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E30-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bbf65af5-650a-4d7d-b61e-fe007123ff68', 'S02E06 — Abordagem a agências pelo LinkedIn — André Ribeiro', 'André Ribeiro', NULL, '', 58, '<div id=\"panda-bbf65af5-650a-4d7d-b61e-fe007123ff68\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E06-3.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bc0897bb-e608-46fc-8feb-2ed1ee8a7295', 'S07E17 — A Tradução Financeira com Dinaura Julles — Dinaura Julles', 'Dinaura Julles', NULL, '\"A Tradução financeira só abrange assuntos considerados difíceis? Impostos e Reforma Tributária, Fusões e Aquisições (M&A), Falência e Recuperação Judicial, Seguros.\n\nO objetivo da palestra é contextualizar a tradução financeira no campo da tradução técnica e apresentar suas especificidades. E também “desmistificar” a ideia de que são traduções difíceis, que partem de textos originais já pouco compreensíveis. A partir do conhecimento dos conceitos e de algumas práticas diferentes nos Estados Unidos e no Brasil - que representam a maioria dos nossos trabalhos - e do domínio dos termos essenciais de temas que vão de impostos a seguros, passando por fusões e aquisições e falência e recuperação judicial, é possível realizar boas traduções de português para inglês e vice-versa.\"', 53, '<div id=\"panda-bc0897bb-e608-46fc-8feb-2ed1ee8a7295\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E17-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('bc363035-ffaf-4d6f-b831-0fe65a5b5233', 'S05E23 — Quality Assurance no cliente: o outro lado da mesa — Priscila Mottola', 'Priscila Mottola', NULL, 'Sobre QA, em geral fala-se pouco. Sobre QA do lado do cliente, então? Só em ano bissexto. Entender a dinâmica e as expectativas do processo de QA no cliente pode virar a chave do seu trabalho, quer você se depare oficialmente com essa etapa ou não. Uma conversa que convida você a considerar seu papel, qualquer que seja, a partir de outra perspectiva.', 69, '<div id=\"panda-bc363035-ffaf-4d6f-b831-0fe65a5b5233\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E23-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bc3e9a4b-81a5-4a45-9506-df1c38794c14', 'S05E43 — Tudo que eu posso dizer sobre tradução audiovisual sem quebrar nenhum sigilo — Daniel Erlich', 'Daniel Erlich', NULL, 'O mercado de streaming cresceu muito, expandiu e se diversificou, em muitos sentidos. Com isso, os produtos linguísticos e fluxos de trabalho dos tradutores que suportam esse mercado altamente internacional também vêm evoluindo e amadurecendo. Daniel Erlich vai contar sobre as suas experiências como tradutor de AV - sem quebrar nenhum sigilo, é claro, pois já adianta que confidencialidade é o fator mais importante na área.', 122, '<div id=\"panda-bc3e9a4b-81a5-4a45-9506-df1c38794c14\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E43-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bc65269b-f840-4928-90a4-e33cd4744967', 'S03E41 — Em busca da naturalidade — Petê Rissatti', 'Petê Rissatti', NULL, 'Nesta palestra/bate-papo, abordaremos um dos temas mais discutidos na tradução de forma gera: a naturalidade. Com exemplos e alguns exercícios práticos, veremos tópicos como público-alvo, revisão, pesquisa e leitura, em um panorama amplo sobre a busca da naturalidade.', 118, '<div id=\"panda-bc65269b-f840-4928-90a4-e33cd4744967\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E41-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bcba7f03-4aae-40a0-b66f-db04b013f248', 'S06E05 — Interpretando Altas Autoridades — Cláudia Chauvet', 'Cláudia Chauvet', NULL, 'O desafio de interpretar altas autoridades, chefes de estado e de governo exige não somente conhecimento linguístico, político, econômico e geográfico, mas bastante \"jogo de cintura\". A experiência técnica e profissional do(a) intérprete conta muito, mas saber fazer a leitura do momento e da atmosfera tem valor igual ou maior para a ocasião da interpretação em si.', 78, '<div id=\"panda-bcba7f03-4aae-40a0-b66f-db04b013f248\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E05-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bcfb25c8-8ac7-43a0-9504-b2a2e190cdfb', 'S05E50 — Termos de negócios e finanças que todo tradutor deve conhecer — Isa Mara Lando', 'Isa Mara Lando', NULL, 'Termos de negócios e finanças que todo tradutor deve conhecer', 98, '<div id=\"panda-bcfb25c8-8ac7-43a0-9504-b2a2e190cdfb\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E50-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bd6705f8-07a1-435b-ab58-d326ead7defc', 'S08E07 — Regex aplicado ao memoQ — Matheus Fabris', 'Matheus Fabris', NULL, '', 110, '<div id=\"panda-bd6705f8-07a1-435b-ab58-d326ead7defc\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E07-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('bdcb662c-2a0e-4371-b974-d04780199a78', 'S05E49 — Arquivar, organizar e traduzir — Any Marry', 'Any Marry', NULL, '', 60, '<div id=\"panda-bdcb662c-2a0e-4371-b974-d04780199a78\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E49-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('be36ca65-d84e-4b93-84f5-7960c390ab22', 'S06E20 — A importância do networking para o tradutor — Felipe Tomasi', 'Felipe Tomasi', NULL, 'Embora tenha começado a carreira de tradutor em 2010, demorei para fazer networking. Por muitos anos, tive dificuldades em conhecer outros tradutores e participar de congressos de tradução. No entanto, resolvi enfrentar o desafio e comecei a participar de congressos e webinars. Nessa palestra, quero mostrar como o networking pode alavancar a carreira do tradutor e os frutos decorrentes da participação em eventos e do contato com colegas.', 58, '<div id=\"panda-be36ca65-d84e-4b93-84f5-7960c390ab22\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E20-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('bee8d18e-063d-4060-b5eb-cfff91f160b4', 'Normas ISO/NBR para Tradução e Interpretação. E agora? ', 'Ricardo Souza', NULL, '', 121, '<div id=\"panda-bee8d18e-063d-4060-b5eb-cfff91f160b4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Live-sobre-normas-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('beeab942-8947-43a3-81c5-87d8ee8f5764', 'S08E06 — Tradução e tecnologia: até que ponto elas caminham juntas? — Simone Brito', 'Simone Brito', NULL, '', 78, '<div id=\"panda-beeab942-8947-43a3-81c5-87d8ee8f5764\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S08-HR/S08E06-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('bf2d9642-af5e-4d6d-823d-bc5b33d1fa96', 'S02E01 — Primeiros passos na tradução literária — Cláudia Mello Belhassof', 'Cláudia Mello Belhassof', NULL, '', 98, '<div id=\"panda-bf2d9642-af5e-4d6d-823d-bc5b33d1fa96\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E01-2.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('c0e71510-4af2-4f5d-bd30-55df67e73c8b', 'S02E05 — Desvendando o Proz — Fernanda Rocha', 'Fernanda Rocha', NULL, '', 91, '<div id=\"panda-c0e71510-4af2-4f5d-bd30-55df67e73c8b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E05-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('c14a5df0-df13-41e0-9f21-413e6b2c1f65', 'S05E36 — Os paralelos entre o trabalho do tradutor dos serviços de inteligência e o trabalho do tradutor freelancer — Melissa Harkin', 'Melissa Harkin', NULL, 'O trabalho de um tradutor dos serviços de inteligência não é sentar em um canto e simplesmente traduzir o dia todo. O foco do trabalho é fazer análises. Para isso, diversas habilidades e conhecimentos são necessários para que o produto dessa análise possa ser usado. Além disso, é preciso trabalhar em equipe. O trabalho de um tradutor freelancer não é muito diferente. Nesta palestra, você aprenderá um pouco sobre o trabalho de um tradutor dos serviços de inteligência e como usar os mesmos métodos e ferramentas para melhorar a qualidade do serviço que você oferece.', 145, '<div id=\"panda-c14a5df0-df13-41e0-9f21-413e6b2c1f65\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E36-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('c1997bc5-372a-4050-b27f-d742578717b8', 'S07E44 — A tradução de literatura sul-coreana no Brasil: oportunidades e desafios — Núbia Tropéia', 'Núbia Tropéia', NULL, '', 66, '<div id=\"panda-c1997bc5-372a-4050-b27f-d742578717b8\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E44-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('c42bbac4-48fb-486a-b37b-481dee30e3e0', 'S06E13 — Da tradução à versão: novos desafios para uma tradutora emigrante — Simone Campos', 'Simone Campos', NULL, 'Simone revela como se iniciou na profissão de tradutora no Brasil e fala sobre sua transição de tradutora técnica a literária. Serão comentadas algumas obras marcantes nessa trajetória, como Os testamentos (Margaret Atwood) e A história secreta de Twin Peaks (Mark Frost). Por fim, ela conta como sua experiência morando nos EUA durante 4 anos alicerçou seu ingresso no mercado da versão português-inglês, revelando também o desafio das adaptações nas versões do quadrinho distópico \"Trato sujo\" (de PJ Kaiowá) e do romance LGBTQI+ Elvis e Madona, de Luís Biajoni.', 79, '<div id=\"panda-c42bbac4-48fb-486a-b37b-481dee30e3e0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E13-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('c4ad7105-e5af-42e9-86d0-73ff23ad111d', 'S03E46 — Rock’n roll x livros (histórias+idiomas+mistura cultural) ideias = tradutora literária — Amarilis Okida', 'Amarilis Okida', NULL, 'Uma parte considerável das histórias presentes no cotidiano das pessoas é traduzida, mas esse detalhe costuma passar totalmente despercebido, que maravilha! Sinal de que o trabalho foi bem executado! A apresentação sobre tradução literária visa oferecer um panorama geral da figura do tradutor que atua nesse nicho de mercado e algumas peculiaridades da área, com base nas minhas próprias experiências, desde o primeiro contato com a editora até a entrega do projeto finalizado. Ah, estudos de “causos” não vão faltar!', 95, '<div id=\"panda-c4ad7105-e5af-42e9-86d0-73ff23ad111d\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E46-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
