('cedc625e-015d-4f61-a665-0f2e2697f466', 'S03E11 — Os desafios da interpretação nos eventos esportivos — Rosita Belinky', 'Rosita Belinky', NULL, '', 77, '<div id=\"panda-cedc625e-015d-4f61-a665-0f2e2697f466\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E11-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('cef2532b-cfa6-4a0d-8354-775781ae875a', 'S05E38 — As palavras e nossa mitologia pessoal — André Gabeh', 'André Gabeh', NULL, 'André falará sobre a influência do vocabulário em nossas escolhas estéticas e sobre a importância de entender nossa sensibilidade a alguns símbolos.', 93, '<div id=\"panda-cef2532b-cfa6-4a0d-8354-775781ae875a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E38-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('cf00bc48-d833-4e09-9c64-6631711320fd', 'Terças da Cultura II ', 'Isa Mara Lando', NULL, 'Mais uma nova atividade que passa a fazer parte do que oferecemos na Translators101: Terça-feira da Cultura, com Isa Mara Lando! Isa conversará por uma hora sobre duas músicas, um filme e um livro. A ideia é aprimorar nosso repertório cultural.', 73, '<div id=\"panda-cf00bc48-d833-4e09-9c64-6631711320fd\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/TERCA-FEIRA-2-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('cf8f0150-b8cf-41f0-9cac-4cb608e012b1', 'Spin-off_13 ', 'Camila Rodrigues', NULL, '', 90, '<div id=\"panda-cf8f0150-b8cf-41f0-9cac-4cb608e012b1\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/SPIN-OFF_13-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('d10885e9-da69-43f5-b1c2-381ce9058d25', 'Especial finanças — Como planejar uma boa aposentadoria', 'Isabela Fontanella', NULL, 'Como planejar uma boa aposentadoria sendo tradutor e com uma renda irregular ao longo do ano? Um dos melhores produtos disponíveis no mercado são as previdências privadas – que nos dão flexibilidade e garantem bons resultados financeiros. Neste bate-papo, vou te ensinar a escolher o melhor produto (e não cair na conversa do gerente), como planejar investimentos sem uma renda estável e, claro, esclarecer todas as dúvidas sobre esse assunto.', 103, '<div id=\"panda-d10885e9-da69-43f5-b1c2-381ce9058d25\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ISABELA-aposentadoria-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('d20ecf7a-cf65-4933-bdf2-5d3757843ed1', 'S06E17 — TQAuditor grátis para tradutores — Jean Trindade', 'Jean Trindade', NULL, 'O objetivo desta palestra é mostrar como usar a função gratuita do TQAuditor para comparar arquivos bilíngues de tradução. Com ele, é possível gerar um relatório de alterações para conferir o que mudou em uma tradução após sua revisão. É útil tanto para tradutores quanto para revisores. O TQAuditor é uma ótima ferramenta para revisores fornecerem um feedback mais completo. Veremos os formatos compatíveis, as opções disponíveis do sistema, a exportação dos relatórios em Excel e dicas para entregar um feedback de qualidade.', 46, '<div id=\"panda-d20ecf7a-cf65-4933-bdf2-5d3757843ed1\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E17-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d226a54f-a5f7-43b2-beeb-c4ad602a926f', 'T101+Phorte ', 'Maria Rosario Garcia Nieves', NULL, '', 94, '<div id=\"panda-d226a54f-a5f7-43b2-beeb-c4ad602a926f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101-Phorte-Rosario-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('d23dddd0-5878-4fe8-a294-aad8792c5050', 'S03E39 — Tradução de patentes: por onde começar? — Beatriz Araújo', 'Beatriz Araújo', NULL, '', 79, '<div id=\"panda-d23dddd0-5878-4fe8-a294-aad8792c5050\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E39-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d2b82d6a-c06e-41bb-9579-1ba0859b3ce2', 'S03E14 — O tradutor nômade digital — Carmen Reis', 'Carmen Reis', NULL, 'Como nômade digital, o tradutor pode e deve aproveitar a oportunidade de poder trabalhar em qualquer lugar a qualquer momento. O intuito desta palestra é compartilhar a minha experiência como tradutora que une duas paixões: a profissão e a vontade de viajar. Pretendo oferecer dicas de planejamento e ferramentas que nos auxiliam nesse processo, como aplicativos e software. Sobretudo, pretendo compartilhar a minha experiência em quatro momentos cruciais do meu trabalho remoto: um ano semissabático (acompanhado de uma viagem de carro pelos EUA de quase um mês), curso de cinco semanas no sul da França, uma viagem ao Japão e uma viagem a Cuba. A ideia é comentar o que deu certo, quais foram os desafios e o que eu poderia ter feito diferente.', 98, '<div id=\"panda-d2b82d6a-c06e-41bb-9579-1ba0859b3ce2\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E14-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d396edfc-7e58-4ef8-9cde-c1b6aac79b6a', 'S07E12 — É possível distinguir a tradução automática da tradução humana? Uma perspectiva baseada em corpus e aprendizagem de máquina — Aline Tomasuolo', 'Aline Tomasuolo', NULL, 'Essa pergunta intrigante virou tema de mestrado. Em um estudo inovador, Aline comparou traduções automáticas e traduções humanas do português para o inglês e textos em inglês nativo com uma amostragem de mais de 3 milhões de palavras. A resposta foi surpreendente. Embora o algoritmo não tenha detectado diferenças gramaticais significativas entre os três tipos de texto, a precisão na distinção lexical entre traduções automáticas e humanas atingiu incríveis 80% de taxa de acerto. Nessa palestra, vamos conversar sobre a trajetória dessa pesquisa e as possíveis implicações no mundo da tradução.', 73, '<div id=\"panda-d396edfc-7e58-4ef8-9cde-c1b6aac79b6a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E12-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('d40e959c-6ce7-4bbe-a2a4-c0a8c765add4', 'S06E04 — Inventar o trabalho dos outros? — Carlos Rutz', 'Carlos Rutz', NULL, 'Teorias à parte, a prática exige de quem traduz um arsenal de soluções ora geniais, ora óbvias, mas que às vezes são meras saídas honrosas. De onde vêm essas soluções? Tem pra vender? Frequentemente, nossa jornada perde a tão preciosa fluidez diante das decisões a serem tomadas. Ossos do ofício. Mas... quanto do que fazemos é inventado por nós? E quando o trabalho do autor vira apenas (se tanto) inspiração para nossa criação no idioma de destino? Carlos nos convida a jogar uma luz nessas questões pra enxergar nosso papel, o de quem (também) inventa o trabalho dos outros.', 113, '<div id=\"panda-d40e959c-6ce7-4bbe-a2a4-c0a8c765add4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E04-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d4190580-2833-4b9f-9468-76e99051829c', 'Especial #ITD 2020 — T101 explica Xbench', 'Mitsue Siqueira', NULL, '', 61, '<div id=\"panda-d4190580-2833-4b9f-9468-76e99051829c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Mitsue-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('d535fad7-57c3-490d-b07a-97ef8ea74c49', 'S05E42 — Da tendência à palavra: uma introdução à tradução de moda — Júlia Jacóbi', 'Júlia Jacóbi', NULL, 'Uma área muito comum e presente no cotidiano, a moda é muitas vezes considerada algo supérfluo e/ou corriqueiro. Mas será que traduzir moda é tão simples assim? O que é, afinal, a tradução de moda? Com que tipo de material esta área técnica da tradução trabalha? Como se especializar nessa área e onde encontrar termos técnicos? Estas são algumas questões que Júlia abordará nesta palestra.', 56, '<div id=\"panda-d535fad7-57c3-490d-b07a-97ef8ea74c49\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E42-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d54eecf6-3881-497f-90be-dfc0265de3be', 'S07E28 — Masterclass Inteligência Artificial em 2024 — Ivan Martucci, Guilherme Gama e Ligia Sobral Fragano', 'Ivan Martucci, Guilherme Gama e Ligia Sobral Fragano', NULL, 'O que é Inteligência Artificial em 2024? Entenda a diferença básica entre algoritmos e aprendizado de máquina. Veja por que essa tecnologia será transformadora e o que você precisa para se preparar para um futuro que chega cada vez mais rápido. Esta masterclass será oferecida pela equipe da Avellan, a plataforma de legendagem automática da Little Brown Mouse. Após a sessão, apresentaremos nosso projeto. Não perca!', 102, '<div id=\"panda-d54eecf6-3881-497f-90be-dfc0265de3be\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E28-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('d61e277f-22b9-442e-a648-1814bba51758', 'S07E05 — Tradução para dublagem de língua turca — Leandra Machado', 'Leandra Machado', NULL, 'Esta palestra irá tratar da estrutura da língua turca em comparação a língua portuguesa e uma análise da tradução para dublagem de trechos da série da Netflix \"Kubra\" partindo dos conceitos de tradução direta e indireta.', 60, '<div id=\"panda-d61e277f-22b9-442e-a648-1814bba51758\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E05-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('d6c22e20-d215-4d1c-ba8c-e45a1f93bb59', 'S04E19 — Traduzir Machado de Assis: causos e percalços do Bruxo além-fronteiras — Pablo Cardellino', 'Pablo Cardellino', NULL, 'Machado de Assis, maior nome da literatura brasileira, percebia a importância da tradução para seu projeto literário. No entanto, seus esforços junto á casa Garnier não deram resultado, e sua viagem por outras línguas começou de forma tardia e demorada. No entanto, foi uma viagem cheia de vicissitudes e felicidades, que confirmou a percepção que o Bruxo tinha sobre a tradução.\nEsta palestra tem dois propósitos: primeiro, pontuar alguns momentos marcantes e representativos da história de Machado de Assis em outras línguas, e posteriormente tentar compreender, em alguma medida, como o texto machadiano facilita e dificulta a vida dos tradutores com alguns exemplos retirados de traduções para o espanhol.', 125, '<div id=\"panda-d6c22e20-d215-4d1c-ba8c-e45a1f93bb59\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E19-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d801dfeb-c369-469e-92b5-6c992c1b9242', 'S04E18 — As novas práticas de legendagem com o avanço do streaming — Ygor Blanco', 'Ygor Blanco', NULL, 'As mudanças no processo de criação de legendas com o avanço rápido dos serviços de streaming, comparando com os padrões de legendagem da televisão - desde a forma de marcar o tempo das legendas até a censura dos palavrões.', 105, '<div id=\"panda-d801dfeb-c369-469e-92b5-6c992c1b9242\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E18-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d9584775-418d-4d17-afef-86d15cf7c65a', 'S06E19 — Desafios ao traduzir um artigo científico do inglês indiano ao português — Sofia Pulici', 'Sofia Pulici', NULL, 'Estamos tão acostumados a traduzir textos do inglês americano ou britânico que às vezes nos esquecemos que existem outras variantes do inglês mundo afora, com seus próprios desafios e características. Nesta palestra, farei uma apresentação de diversos desafios (relacionados à gramática, pontuação, entendimento de terminologia etc.) encontrados ao traduzir um artigo científico escrito originalmente em inglês indiano e contendo terminologia da Medicina Ayurveda.', 57, '<div id=\"panda-d9584775-418d-4d17-afef-86d15cf7c65a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E19-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('d9f4b187-5942-4df7-b2a6-46d2e12b1673', 'S03E24 — AMA (Ask me anything) sobre localização de jogos! — Paula Ianelli', 'Paula Ianelli', NULL, 'Você tem alguma pergunta sobre localização de jogos? Qualquer uma? Então você não pode perder essa sessão de AMA com Paula Ianelli, tradutora de jogos AAA. As perguntas poderão ser feitas na hora.', 122, '<div id=\"panda-d9f4b187-5942-4df7-b2a6-46d2e12b1673\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E24-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('da797bb8-cf66-41a1-99c5-237a9176047f', 'S06E01 — SEO - Sites que agradam o Google — Teresa Sousa', 'Teresa Sousa', NULL, '', 73, '<div id=\"panda-da797bb8-cf66-41a1-99c5-237a9176047f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E01-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('dae4b948-003a-46d9-b755-6bbd6a4e8965', 'S05E37 — O papel vital de comunicação do revisor — Marsel de Souza', 'Marsel de Souza', NULL, 'As responsabilidades do revisor vão além da mera eliminação de erros e falhas no texto. É seu dever também oferecer feedback ao contratante acerca da qualidade da tradução. Nesta apresentação, Marsel tratará da importância da conduta criteriosa não apenas na revisão, mas em algo que pode exigir ainda mais do revisor: a comunicação de um feedback útil e preciso ao contratante quando este não fala/entende a língua da tradução. Mostrará o valor dessa habilidade também para além da função de revisão. Além de falar sobre fatores que influem no trabalho do revisor e identificaremos sinais de maturidade em sua relação com o tradutor e o contratante.', 84, '<div id=\"panda-dae4b948-003a-46d9-b755-6bbd6a4e8965\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E37-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('db51caf2-21e0-4939-8342-d312ca686443', 'S05E44 — Tradução animal! Uma ou duas coisinhas que você precisa saber antes de se aventurar nos textos de medicina veterinária — Luciana Bonancio', 'Luciana Bonancio', NULL, 'Nesta conversa com Luciana Bonancio vamos dar uma olhada no grande mercado da saúde animal e analisar algumas diferenças entre humanos e animais que podem ajudar na hora de traduzir um texto de medicina veterinária. Vai ser o bicho!', 81, '<div id=\"panda-db51caf2-21e0-4939-8342-d312ca686443\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E44-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('db6e7ca5-f291-4184-a46a-c40ebd338930', 'Spin-off_21 ', 'Alquimistas da localização', NULL, '', 109, '<div id=\"panda-db6e7ca5-f291-4184-a46a-c40ebd338930\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('dbec9252-a095-11f0-916e-bad1eb27008a', 'S08E27 — Linguagem imples: um novo campo de atuação para profissionais da tradução', 'Paula Salem Carpio', 'Argentina de nascimento, ela vive em Porto Alegre desde 2011. É formada em Letras pela Universidade Federal do Rio Grande do Sul – UFRGS e mestranda na mesma instituição. É produtora editorial, tradutora e revisora. Especialista em Linguagem Simples e diretora operacional da Agência Clara e Simples.', 'Subsistir como profissional da tradução nunca foi tarefa fácil, mas, nos últimos anos, tem ficado ainda mais difícil. Se antes tínhamos dificuldade para vender nosso serviço, situação não melhorou com o uso massivo e gratuito de tradutores automáticos neurais e, mais recentemente, a tradução por IA. Esse cenário de constante instabilidade faz com que o tradutor profissional precise exercitar sua capacidade de se reinventar para achar novos nichos de atuação profissional.\r\nE é precisamente sobre um desses novos nichos que a Clara e Simples quer falar na conversa com assinantes da Translators101: a Linguagem Simples, uma área em que o profissional da tradução tem muito a acrescentar.', 86, '<div style=\"position:relative;padding-top:38.59899928520372%;\"><iframe id=\"panda-742f3e1f-e0be-4f18-a011-b406f315520d\" src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174\" style=\"border:none;position:absolute;top:0;left:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"100%\" height=\"100%\" fetchpriority=\"high\"></iframe></div>', '/v/images/thumbnails/S08-HR/thumb_68f3f4591e666.png', '/v/images/thumbnails/S08-HR/lecture_68e02f22d59f2.png', 'Língua', '[\"língua\"]', '2025-10-03 20:16:34', '2025-10-18 20:11:05', 0, 0, 'pt-BR', ''),
('dc96288d-ec99-40b2-a38e-95ebd5947c21', 'S04E21 — Tradução técnica – Recursos e desafios — Sónia Tavares', 'Sónia Tavares', NULL, 'Creio que o maior desafio da tradução técnica é conseguir transmitir uma mensagem complexa através de linguagem simples (Plain Language), percetível por todos os leitores, independentemente do seu nível de competência linguística.\nO perfil do tradutor técnico, o mercado da tradução técnica, o tipo de documentos, as normas e certificações, entre outros, serão alguns dos temas abordados nesta sessão.\nPara concluir, serão apresentados alguns recursos valiosos no âmbito da tradução técnica. No final, terei todo o prazer em trocar ideias com os colegas presentes, pois partilhar é receber em dobro!', 130, '<div id=\"panda-dc96288d-ec99-40b2-a38e-95ebd5947c21\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E21-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('dd1a6e7f-e4df-4caa-aaa6-a4419e79f707', 'S06E24 — Tradução criativa na localização de jogos — Ivan L. Lopes', 'Ivan L. Lopes', NULL, '', 143, '<div id=\"panda-dd1a6e7f-e4df-4caa-aaa6-a4419e79f707\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E24-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ddbd6404-fd64-48fc-9279-15ea8348521e', 'LBM Week ', 'Guilherme Gama', NULL, '', 91, '<div id=\"panda-ddbd6404-fd64-48fc-9279-15ea8348521e\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/LBM-Week-Guilherme-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('ddf1d614-dcd6-40cf-8914-5384e11fd4fc', 'S03E01 — A culinária em legendas — Carolina Selvatici', 'Carolina Selvatici', NULL, '', 91, '<div id=\"panda-ddf1d614-dcd6-40cf-8914-5384e11fd4fc\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E01-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('de0e0778-0894-4fa4-81ca-10968bbb994c', 'S06E03 — Esports e jogos digitais competitivos - O que são, por que são importantes e casos de tradução e interpretação — Bhernardo Viana', 'Bhernardo Viana', NULL, 'O mundo dos jogos digitais é muito conhecido por várias pessoas. Muitos já baixaram um jogo no celular ou viram parentes e amigos jogando alguma coisa. Mas mesmo para quem conhece os games, o mundo dos esportes eletrônicos ainda é um mistério. O que são, afinal, os esports? Como as pessoas vivem disso, por que são uma tendência e qual é a situação da tradução no ramo?', 88, '<div id=\"panda-de0e0778-0894-4fa4-81ca-10968bbb994c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E03-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('deef8006-aaf7-4c9b-8795-be4d643a56bb', 'S05E40 — Born to be global - A importância da tradução de SEO — Luana Santos', 'Luana Santos', NULL, 'O que é SEO e SEM? Como este serviço pode impactar seu cliente que deseja atuar em mercados globais? Atuar em um novo país e produzir um produto globalizado exige que as estratégias de marketing estejam alinhadas com as estratégias linguísticas. \nComo tradutores, devemos analisar a situação do cliente, entender suas necessidades e oferecer o serviço correto para que nosso trabalho seja eficaz. A tradução de SEO caminha juntamente com a comunicação intercultural e desempenha papel fundamental no sucesso de grandes empresas. Nesta palestra, Luana Santos discutirá sua importância e quais ferramentas os tradutores podem utilizar para melhor desempenhar seu trabalho.', 78, '<div id=\"panda-deef8006-aaf7-4c9b-8795-be4d643a56bb\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E40-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('df00ca87-2a43-46cf-bfcf-9de104f41ed5', 'S03E27 — Traduzindo para a cena — Cláudia Cruz', 'Cláudia Cruz', NULL, 'O que distingue a tradução de um texto dramático dos outros tipos de tradução? Quais são os aspectos específicos da tradução desses textos? Que diferenças há no processo de tradução de um texto dessa natureza para ser lido ou para ser encenado? A proposta desta palestra é refletir a respeito dessas questões, abordando conceitos teóricos a partir de exemplos concretos. Falaremos das especificidades desse tipo de tradução, passando por temas como ritmo, registro, aspectos culturais e linguísticos, uso de referências, jogos de palavras, piadas, entre outros.', 113, '<div id=\"panda-df00ca87-2a43-46cf-bfcf-9de104f41ed5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E27-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e0483cc4-a1cc-43ea-b59e-f53e4ab52c36', 'Especial #ITD 2020 — T101 Explica memoQ', 'Val Ivonica', NULL, 'Conheça o básico da ferramenta memoQ.', 67, '<div id=\"panda-e0483cc4-a1cc-43ea-b59e-f53e4ab52c36\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/ITD-2020-Val-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e0d02824-a31d-4b9b-bb14-7aaf36b1aed2', 'S05E45 — Qualidade da tradução na era da revolução tecnológica — Aline Tomasuolo', 'Aline Tomasuolo', NULL, 'Logo após a revolução industrial, vimos o nascimento da área de “controle de qualidade”, fundamental para reduzir erros e garantir uma qualidade consistente. O mercado de tradução passa agora por uma revolução similar. Tradução automática avançada, CAT tools cada vez mais sofisticadas, inúmeros softwares de revisão textual. A revolução tecnológica transformou completamente os métodos de tradução. Ferramentas e metodologias de controle de qualidade podem e devem ser adotadas no dia a dia de todos os tradutores. Nessa palestra, vamos conversar um pouco com Aline Tomasuolo sobre como implementar um controle de qualidade eficaz usando todas as ferramentas tecnológicas em favor do tradutor e uma tradução de qualidade.', 98, '<div id=\"panda-e0d02824-a31d-4b9b-bb14-7aaf36b1aed2\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E45-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e0d39a51-db91-48fa-821e-28a027782e1f', 'S04E31 — De intérprete infantil oficial da família a intérprete profissional! — Katia Georges Chedraoui', 'Katia Georges Chedraoui', NULL, 'Eu nasci no Líbano e fui criada no Brasil, desde pequena fui tradutora e intérprete do meu avô, pois ele não falava português e eu gostava e não me importava de ficar o dia todo traduzindo pra ele tudo absolutamente tudo, como muitos filhos de imigrantes sempre traduzimos aos parentes que não falam o português.\nPelo meu avô conheci o Líbano morando em Petrópolis, ele me contava do povo, da comida do poeta Kalil Gebram que foi amigo dele, das praias lindas e claro da beleza do Líbano e dos libaneses, mas eu precisava ver para acreditar. Aos meus 14 anos eu fui conhecer esse país que tanto me falaram dele. Eu vi, acreditei e me encantei. Me encantei pela beleza do país, pelo povo tão acolhedor e claro pelo idioma que eu já conhecia e falava fluente, mas é diferente estar ali com eles, andar nas ruas de Beirute e estudar nas escolas Libanesas.\nConheci o Líbano de norte a Sul, fui professora de poesia e ainda dei aulas como ajudante de professor na escola. Foi no Líbano que conheci que existia uma profissão que se chama Tradução, como assim? Sim, acompanhei o meu tio para uma reunião na embaixada e fui sua intérprete consecutiva profissional aos meus 14 anos.\nQuer saber? Foi muito fácil. Eu acredito sim que o meu avô foi meu grande professor.', 102, '<div id=\"panda-e0d39a51-db91-48fa-821e-28a027782e1f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E31-2.png', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e115bc97-c065-4877-8463-d31ed9d3c846', 'Yoga nidra ', 'Sofia Pulici', NULL, '', 43, '<div id=\"panda-e115bc97-c065-4877-8463-d31ed9d3c846\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/YOGA-NIDRA-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e282485d-a9f0-4d08-94c7-a39bacf82e2a', 'Oficina de LinkedIn II ', 'Karine Souto', NULL, '', 61, '<div id=\"panda-e282485d-a9f0-4d08-94c7-a39bacf82e2a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/OFICINA-LINKEDIN-2-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e2a626e9-4812-424a-9c32-94cf3d70dd8f', 'Semana Intensiva — Produtividade', 'André Ribeiro', NULL, '', 69, '<div id=\"panda-e2a626e9-4812-424a-9c32-94cf3d70dd8f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Semana-Intensiva-Produtividade-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e2e6e4f7-6068-4346-a824-ebfad3a8102f', 'S06E48 — Ensaio sobre a curiosidade: como os verbos errar, aprender e mudar devem ser um mantra — Rafaela Mota Lemos', 'Rafaela Mota Lemos', NULL, 'Ficamos sempre muito inspirados quando ouvimos histórias de tradutores que estão na profissão há 20, 30 ou 40 anos.\nFomos ensinados desde sempre que estabilidade e consistência eram virtudes fundamentais de um bom profissional.\nQuem faz sempre o mesmo recebe um certificado imediato de credível. Quem muda e faz diferente muitas vezes é considerado de sonhador, errático ou sem foco. Será mesmo assim?\nNesta palestra, gostaria de partilhar com a audiência o meu percurso pouco linear enquanto tradutora e as lições que fui aprendendo no processo.\nSpoiler alert: não faz mal experimentar outras coisas, criar outras formas de subsistência e seguir outras carreiras.', 59, '<div id=\"panda-e2e6e4f7-6068-4346-a824-ebfad3a8102f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E48-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL);
INSERT INTO `lectures` (`id`, `title`, `speaker`, `speaker_minibio`, `description`, `duration_minutes`, `embed_code`, `thumbnail_url`, `image`, `category`, `tags`, `created_at`, `updated_at`, `is_featured`, `is_live`, `language`, `level`) VALUES
('e3d2be63-58f1-45fd-897f-af1674a238a0', 'Oficina — Tradução e edição de literatura especulativa', 'Gi Bomentre', NULL, 'Nesta oficina, Giovana apresentará a introdução ao processo editorial e estudos de casos para edição e tradução de neologismos em fantasia e ficção científica, explorando os pontos de atenção e outros potenciais desafios destes gêneros.', 169, '<div id=\"panda-e3d2be63-58f1-45fd-897f-af1674a238a0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Oficina-Giovana-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e5c63e14-e00a-4929-ab10-f287dec0e39f', 'Maratona — LinkedIn', 'André Ribeiro', NULL, '', 105, '<div id=\"panda-e5c63e14-e00a-4929-ab10-f287dec0e39f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Maratona-LinkedIn-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('e6a3ae5f-121e-48f1-a4a4-34303f232589', 'S05E47 — Jurídico e ciência na interpretação de noticiário — Denise e Natalie', 'Denise e Natalie', NULL, '', 71, '<div id=\"panda-e6a3ae5f-121e-48f1-a4a4-34303f232589\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E47-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e6ae547b-e31f-4062-b51e-59750a7ddef1', 'S05E20 — Tradutores juramentados: mitos e verdades — Carolina Ventura', 'Carolina Ventura', NULL, 'Tradutor juramentado é funcionário público e ganha um salário super alto sem fazer nada; Tem muito glamour envolvido em ser tradutor juramentado; A “panela” dos tradutores juramentados não deixa abrir concurso para que tenham pouca concorrência; Tradutor juramentado só traduz texto chato, como documentos jurídicos, certidões...\nCom certeza você já ouviu falar algo assim em relação a esse tipo de tradutor, não é?\nNesta palestra, Carolina Ventura apresentará quem é e o que faz o tradutor juramentado, discutindo mitos e verdades a respeito desse profissional tão desconhecido do público em geral e da própria comunidade brasileira de tradutores e intérpretes. Abordará suas peculiaridades em comparação ao tradutor não-juramentado e apresentará as características das traduções que produz. Por fim, explicará como se tornar um TPIC e comentará os desafios atuais relacionados a esse ofício.', 91, '<div id=\"panda-e6ae547b-e31f-4062-b51e-59750a7ddef1\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E20-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e6cc8332-e563-430b-b97b-e0c2e7071f9b', 'S04E36 — Preparação de texto, que bicho é esse? — Laura Folgueira', 'Laura Folgueira', NULL, 'Antes de chegar a ser impresso, um livro passa por inúmeras etapas e, especialmente para quem ainda não trabalha com tradução editorial ou literária e tem a intenção de entrar nesse mercado, é essencial conhecer todos os processos.\nDepois de traduzido, um livro segue para uma etapa muitas vezes desconhecida, mas importantíssima: a preparação de texto ou copidesque, que só costuma existir no mercado editorial.\nEsse é o assunto desta palestra, que abordará técnicas e características de uma boa preparação; escopo do trabalho de preparação; os limites da intervenção no texto do tradutor: quando mexer e quando não mexer; relação com editores. Assim, espera-se que tradutores iniciantes ou aqueles mais experientes, mas que desejam começar no mercado editorial, saiam com um bom panorama.', 119, '<div id=\"panda-e6cc8332-e563-430b-b97b-e0c2e7071f9b\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E36-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e7af9fbf-4696-422f-b655-872dda8f3081', 'S05E34 — Traduzindo Neil Gaiman e outras criaturas fantásticas — Renata Pettengill', 'Renata Pettengill', NULL, 'Um passeio pela experiência de como foi traduzir, de Neil Gaiman, “O oceano no fim do caminho”, “A bela e a adormecida”, “Hora nenhuma: o décimo primeiro doutor” e “Como falar com garotas em festas”. E como essa experiência se compara com a tradução do “A culpa é das estrelas” e “O teorema Katherine”, de John Green, e do “Em busca de Wondla” e “Um herói para Wondla”, de Tony DiTerlizzi, e, por fim, com o “Holy Cow - uma fábula animal”, de David Duchovny.', 90, '<div id=\"panda-e7af9fbf-4696-422f-b655-872dda8f3081\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E34-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('e7b7e1a2-da44-4ede-944d-7f6dbd4fe2c2', 'S07E35 — Perspectivas da carreira do tradutor com a IA — Ricardo Souza, Jorge Davidson, Simone Vieira Resende e Carol Santiago', 'Ricardo Souza, Jorge Davidson, Simone Vieira Resende e Carol Santiago', NULL, 'Um bate-papo sobre as perspectivas da carreira do tradutor com a IA.\nMediação: Caroline Santiago', 82, '<div id=\"panda-e7b7e1a2-da44-4ede-944d-7f6dbd4fe2c2\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E35-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('e999dc79-62ca-4ae3-a369-ec06493cb14f', 'S04E16 — Da Paraíba para o mundo: legendagem de curtas-metragens paraibanos — Victoria Cabral', 'Victoria Cabral', NULL, 'O projeto de extensão \"Da Paraíba para o mundo: legendagem de curtas-metragens paraibanos\" é vinculado ao curso de Bacharelado em Tradução da UFPB.\nDesde 2016, faz tradução e legendagem de obras fílmicas produzidas no estado da Paraíba para viabilizar a participação de cineastas locais em eventos internacionais.\nAo longo de cinco anos, traduziu e legendou 23 curtas-metragens e dois longas-metragens, sobretudo nas línguas espanhola, inglesa e francesa. Seus objetivos também incluem aprimorar técnicas de tradução e de legendagem de discentes extensionistas, além de impulsionar o diálogo multidisciplinar.', 105, '<div id=\"panda-e999dc79-62ca-4ae3-a369-ec06493cb14f\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E16-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('eb990cd3-063c-43bf-9392-ad3d0c64e395', 'S06E39 — Intérpretes pós-pandêmicos: aprendizados além da interpretação — Felipe Pazello', 'Felipe Pazello', NULL, 'A interpretação muitas vezes foi exclusivamente associada a ambientes de conferências acadêmicas, simpósios e encontros de membros do governo. No entanto, particularmente no período pós-pandêmico, a interpretação de reuniões corporativas em caráter online ou híbrido ganhou grande força. A facilidade de se ter licenças de softwares capazes de fornecer canais de áudio separados para a interpretação e a possibilidade de se fazer negociações complexas possibilitou a entrada de muitos novos intérpretes no mercado. Além disso, muitos intérpretes tornaram-se “gerentes de projetos” independentes, não se limitando ao contato com agências e assim estabelecendo um contato direto com os clientes.', 67, '<div id=\"panda-eb990cd3-063c-43bf-9392-ad3d0c64e395\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E39-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('ec0f02a3-63cd-44b2-bd19-6ff56add46cb', 'S07E09 — Percy Jackson e a adaptação na tradução intersemiótica do livro para a tela. — Bianca da Costa', 'Bianca da Costa', NULL, '', 60, '<div id=\"panda-ec0f02a3-63cd-44b2-bd19-6ff56add46cb\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E09-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('ec32c24f-2bbf-47ee-9d13-a7b90097511c', 'S05E46 — Línguas de trabalho: o que são e como mantê-las afiadas — Christiano Sanches', 'Christiano Sanches', NULL, 'Como são classificadas as línguas de trabalho na interpretação? Como manter minhas línguas de trabalho atualizadas e prontas para serem usadas em qualquer circunstância? O que devo fazer quando tenho mais de uma língua de trabalho? Estas são algumas das perguntas que serão respondidas nesta palestra de Christiano Sanches.', 72, '<div id=\"panda-ec32c24f-2bbf-47ee-9d13-a7b90097511c\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E46-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ec5eb201-7a65-4b71-8222-2b04ded3478e', 'CULT e São Camilo ', 'Ana Julia Perrotti', NULL, '', 59, '<div id=\"panda-ec5eb201-7a65-4b71-8222-2b04ded3478e\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101Phorte-2023-Ana-Julia-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('ec6a747a-1b44-4dd9-bf54-8dd5e81a6081', 'S03E25 — Profissão tradutor/intérprete de Libras - trajetórias e formação — Paloma Bueno', 'Paloma Bueno', NULL, 'A palestra terá como objetivo apresentar um pouco da trajetória de formação como tradutora e intérprete de Libras, curiosidades e desafios sobre as áreas de atuação.\nTópicos que serão abordados:\n- Áreas de atuação: educação, novos mercados/RSI.\n- Como se forma um intérprete de Libras?\n- Qual a diferença entre tradução e a interpretação da e para Libras, existe isso?\n- Clientes e usuário de serviço de tradução/interpretação em Libras.\n- Surdos: legendas ou Libras?', 80, '<div id=\"panda-ec6a747a-1b44-4dd9-bf54-8dd5e81a6081\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E25-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ec916c0f-d6f2-4aba-b9e5-da055d4c4bfc', 'Semana intensiva — Gestão de renda', 'André Ribeiro', NULL, '', 84, '<div id=\"panda-ec916c0f-d6f2-4aba-b9e5-da055d4c4bfc\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Semana-Intensiva-Gestao-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('ed4360f0-72e7-4bfc-b7b8-43c0d4d5c2b7', 'S06E09 — É um livro? É um jogo? É uma HQ? A localização de livros-jogos e seus desafios — Bianca Melyna', 'Bianca Melyna', NULL, '', 92, '<div id=\"panda-ed4360f0-72e7-4bfc-b7b8-43c0d4d5c2b7\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E09-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('edda1d98-a086-4884-beba-c237e199d707', 'S05E39 — Do Sul do Brasil ao Norte da América do Norte: como internacionalizei minha carreira no Canadá — Bruna Beatriz', 'Bruna Beatriz', NULL, 'Desde cedo, Bruna sentiu a vontade de viajar para aprender idiomas e já se anunciava um grande amor por cultura e idiomas. Após terminar a faculdade e sem muita certeza de seu próximo passo, uma luzinha se acendeu ao descobrir que a tradução era uma carreira com diversas possibilidades e encantos — que foram se apresentando ao longo do caminho. Com três anos de bagagem tradutória, seu novo norte passaria a ser o \"Plano Canadá\". Hoje, com uma filha que cresce em um ambiente trilíngue, um marido que é apaixonado por games e experiências de trabalho que nunca imaginou ter, Bruna entende que a internacionalização de sua carreira foi o resultado de intuição, necessidade e formações prévias. Venha descobrir com Bruna Beatriz as etapas dessa jornada!', 88, '<div id=\"panda-edda1d98-a086-4884-beba-c237e199d707\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E39-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ede0da99-9176-4ff4-949a-9d5187aec981', 'S01E01 — Treine como um atleta: dicas para o tradutor autodidata', 'Isa Mara Lando', 'Isa Mara Lando já traduziu mais de 100 livros e é autora do “VocabuLando – Vocabulário Prático Inglês-Português”, em catálogo há mais de 20 anos, agora também em versão digital na Amazon. Nos últimos anos tem traduzido muitos materiais para RH e outros fins comerciais, sempre se valendo de uma primeira versão por programa. Na busca de aprimorar suas traduções, vem sistematizando suas técnicas a fim de compartilhar as melhores práticas em suas palestras e oficinas.', 'Isa Mara Lando apresenta um verdadeiro manual para quem deseja se destacar na tradução. Com dicas práticas, ela incentiva o desenvolvimento autodidata, a busca ativa por cultura geral e o aprimoramento constante do inglês e do português. Isa Mara compartilha experiências pessoais, métodos de estudo, importância de viajar, contato com estrangeiros e a necessidade de metas e projetos próprios. Uma palestra cheia de energia, exemplos divertidos e conselhos valiosos para quem quer evoluir diariamente e conquistar espaço no mercado de tradução.', 72, '<div id=\"panda-ede0da99-9176-4ff4-949a-9d5187aec981\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\">\r\n    <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe>\r\n</div>', 'https://translators101.com/images/thumbnails/S01-HR/S01E01-1.jpeg', NULL, 'Geral', '[\"geral\"]', '2025-06-03 21:49:37', '2025-06-07 21:35:47', 1, 0, NULL, NULL),
('ee374e6f-89f5-4b5f-9da8-d8710d77d8f5', 'S02E02 — She-ra e as Princesas do Poder — Deborah Cornélio', 'Deborah Cornélio', NULL, '', 48, '<div id=\"panda-ee374e6f-89f5-4b5f-9da8-d8710d77d8f5\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E02-2.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ef05d364-7be1-4956-a13d-54e8f2beba75', 'S05E25 — VERSÃO BRASILEIRA: os desafios e as alegrias de adaptar canções para o português — Mariana Elisabetsky', 'Mariana Elisabetsky', NULL, 'Entrando em contato com os fundamentos da adaptação musical através de exemplos práticos de filmes e musicais versionados por Mariana Elisabetsky. E ainda um workshop para que você arrisque fazer sua própria adaptação musical. Os interessados receberão o material para versionar com antecedência e Mariana selecionará alguns deles para trabalhar em conjunto com a turma.', 108, '<div id=\"panda-ef05d364-7be1-4956-a13d-54e8f2beba75\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E25-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ef808d10-f13e-4ecf-9467-6da3b43f2770', 'S07E40 — Tort Law 101 e os casos mais bizarros dos EUA — Fernanda Vitarelli', 'Fernanda Vitarelli', NULL, '', 82, '<div id=\"panda-ef808d10-f13e-4ecf-9467-6da3b43f2770\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E40-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('f0068541-eb02-40e6-8636-1ec726ae47f6', 'S05E28 — Linux para tradutores — Rafa Lombardino', 'Rafa Lombardino', NULL, 'Vamos deixar de lado a pergunta clássica \"Mac ou Windows?\" e refletir sobre a possibilidade de trazer o Linux para a nossa vida profissional. Rafa Lombardino, usuária da distribuição Ubuntu Linux há 14 anos e professora de tecnologias na tradução, vai falar um pouco sobre essa opção para quem ainda acredita que não dá para traduzir fora do binômio Apple-Microsoft. Vamos repassar os prós e os contras e ver quais programas, aplicativos e websites podem ajudar você a migrar para uma distribuição Linux sem interromper as suas atividades profissionais como tradutores e intérpretes.', 98, '<div id=\"panda-f0068541-eb02-40e6-8636-1ec726ae47f6\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E28-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f03f9f68-74a5-4165-a8b9-dbe922fe82d6', 'S07E01 — Les casquettes du monde littéraire : navegando entre a criação e a tradução do texto. — Adriana Fernandes Morais Martins', 'Adriana Fernandes Morais Martins', NULL, '', 78, '<div id=\"panda-f03f9f68-74a5-4165-a8b9-dbe922fe82d6\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E01-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('f070b219-bad2-40b5-ada9-868182ce6f67', 'Especial ITD 2023 ', 'Ascanio Roquette', NULL, '', 87, '<div id=\"panda-f070b219-bad2-40b5-ada9-868182ce6f67\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', '', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('f0a51394-0439-4ca5-a3d1-1f05d043e6ee', 'S05E11 — Closed Caption: legenda com emoção — Diego Marsicano', 'Diego Marsicano', NULL, 'Transcrever o que se diz não é representar o que se mostra. Legendar para quem não ouve vai além de apresentar os diálogos falados de um filme em palavras, é ter a sensibilidade de perceber que os sons e os silêncios também geram sentido e, portanto, devem ser descritos para que possam ser entendidos por quem não ouve.', 131, '<div id=\"panda-f0a51394-0439-4ca5-a3d1-1f05d043e6ee\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E11-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f0b8c7c5-2008-4457-b734-4041549e47df', 'T101+Phorte ', 'Simone Resende', NULL, '', 80, '<div id=\"panda-f0b8c7c5-2008-4457-b734-4041549e47df\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101-Phorte-Simone-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('f1617197-43ea-44fc-b80e-1b2d09a8339a', 'S03E16 — Tempos verbais e suas especificidades nas versões de artigos científicos para o inglês — Gilson Mattos', 'Gilson Mattos', NULL, 'Não há dúvidas de que tradutores precisam dominar a gramática dos pares linguísticos com que trabalham. No entanto, por mais avançado que seja o domínio dos tempos verbais em inglês, o que muitos não sabem é que, nos artigos científicos, os tempos verbais têm usos específicos que variam de acordo com as seções do artigo. Nesta palestra, tratarei dessas especificidades, analisando também algumas armadilhas que frequentemente induzem em erro gramatical e comprometem o significado e, consequentemente, a qualidade da tradução.', 80, '<div id=\"panda-f1617197-43ea-44fc-b80e-1b2d09a8339a\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E16-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f1a44e34-f0ec-4a54-bdf3-4fd1f2c3ee05', 'S07E33 — De tradutora literária a escritora — Natalie Gerhardt', 'Natalie Gerhardt', NULL, 'A tradução literária é uma escrita autoral, na qual usamos nossa criatividade e conhecimentos linguísticos e literários para contar, da melhor forma possível, uma história criada por outra pessoa em outro idioma. Nessa palestra, vou compartilhar minha experiência como tradutora e como escritora e trazer uma reflexão sobre como a tradução influencia a minha escrita e vice-versa.', 66, '<div id=\"panda-f1a44e34-f0ec-4a54-bdf3-4fd1f2c3ee05\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S07-HR/S07E33-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:13', 0, 0, NULL, NULL),
('f2ba82df-efda-487d-b003-aa7364014d40', 'S05E09 — Reflexões sobre a criação de recursos visuais a partir de conteúdos textuais — Mariana Casetto', 'Mariana Casetto', NULL, 'Vivemos um momento em que as trocas de informações estão cada vez mais rápidas e visuais. Dessa forma, habilidades relacionadas ao trabalho com materiais visuais podem ser desejáveis e complementar a formação dos profissionais de comunicação, como tradutores, revisores e redatores. A criação de infográficos, resumos visuais e outros recursos visuais a partir de conteúdos textuais tem se mostrado um novo nicho de atuação e é isso o que pretendemos explorar e discutir nesse encontro.', 80, '<div id=\"panda-f2ba82df-efda-487d-b003-aa7364014d40\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E09-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f3b2ce65-98ff-461b-9e40-f1c081fe3e84', 'S02E01 — Dos livros lidos aos livros traduzidos — Carolina Caires Coelho e Petê Rissatti', 'Carolina Caires Coelho e Petê Rissatti', NULL, '', 59, '<div id=\"panda-f3b2ce65-98ff-461b-9e40-f1c081fe3e84\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe></div>', 'https://translators101.com/images/thumbnails/S02-HR/S02E01-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f3ff813e-88c2-4527-8720-3568011afec0', 'S06E25 — Montando passo a passo uma macro no Word — Victor Almeida', 'Victor Almeida', NULL, 'Neste curso básico de macros para Word, você aprenderá a automatizar tarefas repetitivas e agilizar seu trabalho na hora de revisar. Através de uma abordagem prática, vamos criar e executar macros personalizadas. Descubra como gravar ações para tornar suas tarefas diárias mais eficientes.', 52, '<div id=\"panda-f3ff813e-88c2-4527-8720-3568011afec0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E25-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f5c1f20f-1609-4602-be53-27a01b36cb12', 'Terças da Cultura IV ', 'Isa Mara Lando', NULL, 'Mais uma nova atividade que passa a fazer parte do que oferecemos na Translators101: Terça-feira da Cultura, com Isa Mara Lando! Isa conversará por uma hora sobre duas músicas, um filme e um livro. A ideia é aprimorar nosso repertório cultural.', 100, '<div id=\"panda-f5c1f20f-1609-4602-be53-27a01b36cb12\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/TERCA-FEIRA-4-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('f64b49c6-91d4-41af-9555-6eb80d5dcee0', 'S06E31 — I\'ve Known Rivers - A tradução e o mercado editorial sob a perspectiva negra — Karine Ribeiro', 'Karine Ribeiro', NULL, 'Nesta palestra, Karine reflete sobre sua trajetória na tradução e nos bastidores do mercado editorial enquanto mulher negra e periférica, com enfoque na experiência de traduzir e editar os mais diversos gêneros, de biografias de importantes figuras da história negra ao romance contemporâneo jovem escrito por e feito para pessoas negras.', 86, '<div id=\"panda-f64b49c6-91d4-41af-9555-6eb80d5dcee0\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S06-HR/S06E31-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('f69b9e21-afa7-4a58-af20-08794bd2ade4', 'PUC-Rio e Translators101 ', 'Mesa da tradução', NULL, 'A PUC-Rio e a Translators101 apresentam duas mesas com profissionais que falarão sobre o mercado e boas práticas de tradução e interpretação.', 96, '<div id=\"panda-f69b9e21-afa7-4a58-af20-08794bd2ade4\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/T101PUC-Rio-Traducao-HR-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('f79497ed-8e43-4072-a1b4-4e8a1fd2fadd', 'Especial #ITD 2020 — Tradução científica_ trajetória, especialização e peculiaridades', 'Laurieny e Marina', NULL, '', 62, '<div id=\"panda-f79497ed-8e43-4072-a1b4-4e8a1fd2fadd\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;iosFakeFullscreen=true\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0;\" allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" allowfullscreen=true width=\"720\" height=\"360\" fetchpriority=\"high\"></iframe> </div>', 'https://translators101.com/images/thumbnails/Outras/Especial-ITD-2020-Laurieny-e-Marina-HR-1-1536x864.jpeg', NULL, '', '[\"\"]', '2025-07-14 19:31:00', '2025-07-14 19:31:00', 0, 0, NULL, NULL),
('f84bc3a0-fe05-4f1f-a621-d5d3d7d632f2', 'S04E50 — A Sétima Maravilha das Organizações Internacionais — Claudinei Nunes e Mônica Lange', 'Claudinei Nunes e Mônica Lange', NULL, '', 98, '<div id=\"panda-f84bc3a0-fe05-4f1f-a621-d5d3d7d632f2\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E50-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('fa9d3dbc-ec76-4ff4-8433-f26c26362145', 'S05E24 — Localização de games: linguagem e mídia — Horacio Corral', 'Horacio Corral', NULL, 'A indústria de entretenimento digital é uma das maiores do mundo tanto em público, quanto em receita, tendo superado tanto a indústria da música quanto Hollywood. Games são uma mídia de natureza interativa. Os jogos digitais trazem um grande desafio para o tradutor já que, além do conhecimento da língua, a compreensão da linguagem e os conceitos dos games são essenciais para um bom profissional de mercado. A proposta desta palestra é abordar de maneira didática aspectos da tradução de games como internacionalização e localização, ferramentas e conceitos de criação de jogos, mídia e linguagem, e os desafios técnicos que esta mídia tão especial propõem.', 67, '<div id=\"panda-fa9d3dbc-ec76-4ff4-8433-f26c26362145\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S05-HR/S05E24-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('fd09b60f-6562-49fa-8bd8-2f6a05525df1', 'S03E31 — What the heck! A internacionalização da Dona Hermínia — Ligia Sobral Fragano', 'Ligia Sobral Fragano', NULL, '', 67, '<div id=\"panda-fd09b60f-6562-49fa-8bd8-2f6a05525df1\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E31-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('fdf6a4ab-775e-49e9-8072-10916ed16283', 'S04E22 — Sua amiga, a tradução automática — Silvio Picinini', 'Silvio Picinini', NULL, 'A palestra defenderá abertamente o uso de tecnologia para tradução. Vai também falar de algumas coisas certas e erradas que você pode esperar da Tradução Automática e sobre algumas coisas que estão aparecendo nessa área.', 144, '<div id=\"panda-fdf6a4ab-775e-49e9-8072-10916ed16283\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S04-HR/S04E22-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('fe2def83-f97a-41b9-ad84-a45a070ae3ef', 'S03E26 — Ask me anything sobre legendagem — Leilane Papa', 'Leilane Papa', NULL, 'Qual o papel da revisão na legendagem?\nComo é a adaptação na legendagem?\nMarcação de tempos nos shot-changes? \nComo fazer nas interrupções de fala? \nTudo isso e qualquer outra pergunta que você queira fazer!', 74, '<div id=\"panda-fe2def83-f97a-41b9-ad84-a45a070ae3ef\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E26-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL),
('ffc5b162-7d5c-4566-a00a-73c30e4a3623', 'S03E32 — Audiodescrição rima com tradução de muitas maneiras além da sonoridade — Ana Julia Perrotti', 'Ana Julia Perrotti', NULL, 'Venha conhecer as bases da audiodescrição, essa modalidade de tradução intersemiótica que ajuda a compreensão plena de produtos audiovisuais para pessoas com deficiência visual, cegas e com baixa visão, idosos, estrangeiros, pessoas com dislexia e pessoas com visão preservada ou corrigida momentaneamente privadas da visão. Além de ser um mercado de trabalho em franca expansão, carente de bons profissionais e de especialistas dedicados, a audiodescrição pode ser uma especialização frutífera e gratificante para tradutores, intérpretes, narradores e demais profissionais das páreas de teatro, cinema, TV e editoras.', 97, '<div id=\"panda-ffc5b162-7d5c-4566-a00a-73c30e4a3623\" style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;\"> <iframe src=\"https://player-vz-9256cd6f-703.tv.pandavideo.com.br/embed/?v=progress-tracker-174&amp;autoplay=false&amp;muted=false\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" allowfullscreen allow=\"accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture\" frameborder=\"0\"></iframe> </div>', 'https://translators101.com/images/thumbnails/S03-HR/S03E32-1.jpeg', NULL, '', '[\"\"]', '2025-06-10 14:56:57', '2025-06-10 19:32:12', 0, 0, NULL, NULL);
