INSERT INTO `upcoming_announcements` (`id`, `title`, `speaker`, `announcement_date`, `lecture_time`, `description`, `image_path`, `is_active`, `display_order`, `created_at`, `updated_at`) VALUES
('009a00dc0c01b5d5f579b5c6dba518e0', 'No princípio, era o verbo (em 4 línguas): origens da Interpretação Simultânea', 'Jayme da Costa Pinto', '2025-10-23', '18:00:00', 'O ano de 2025 marca 80 anos do Julgamento de Nuremberg, considerado o primeiro evento oficial de nível internacional em que se usou interpretação simultânea nos moldes como a conhecemos hoje, com o público acompanhando em tempo real e ajuda de equipamentos como microfones e fones de ouvido. A palestra cobrirá os avanços na área de interpretação de conferências no período entreguerras (essencialmente na modalidade consecutiva) e os movimentos que resultaram, em 1945, na decisão de se adotar a modalidade simultânea frente às demandas complexas – e inéditas – impostas por um julgamento conduzido em quatro idiomas.', '/images/announcements/announcement_68f27e3282ccd_2025-10-17.png', 1, 9, '2025-10-17 17:34:42', '2025-10-17 17:37:39'),
('1ca474fa-9b25-11f0-916e-bad1eb27008a', 'Tradução de Rimas em Jogos', 'Lucas Rodrigues Oliveira', '2025-10-01', '19:00:00', 'A apresentação vai começar abordando a estrutura da poesia, como funcionam as rimas, a métrica, o ritmo e outros elementos que compõem a poesia rimada. Depois, vão ser mostrados vários exemplos de poesias em português para exemplificar esses elementos.\r\nEm seguida, vão ser apresentados exemplos de traduções de poesias (nas duas direções: inglês para português; e português para inglês). No final, o palestrante vai analisar algumas traduções de autoria própria, mostrando como foi o processo criativo.', '/images/announcements/announcement_68d71056927b0.png', 1, 1, '2025-09-26 22:06:54', '2025-09-26 22:38:50'),
('1ca47719-9b25-11f0-916e-bad1eb27008a', 'Tem TDAH, autismo ou altas habilidades? Então, use seus superpoderes na tradução!', 'Jacqueline Plaça', '2025-10-15', '18:00:00', 'Neurodivergência, sobrecarga sensorial, perfeccionismo, burnout. Se essas palavras têm povoado seu cotidiano, provavelmente você é uma pessoa neurodivergente, ou suspeita ser, ou é neurotípica convivendo com atípicas. Ser neurodivergente é sinônimo de ter superpoderes muito potentes! Nessa palestra, vamos entender quais são eles, o que fazer para lidar com tanta potência sem ter um esgotamento, e, o melhor, como trabalhar com outras pessoas na tradução e interpretação cultivando a saúde mental. As palavras mágicas são: neuroplasticidade, hiperfoco, menu de dopamina e body doubling. Quer saber como usá-las, meu querido colecionador de palavras? Vem comigo e te conto no caminho.', '/images/announcements/announcement_68d7c0a04e750_2025-09-27.png', 1, 3, '2025-09-26 22:06:54', '2025-10-04 18:16:56'),
('2eab5d9bf9823b880313cc45280d43b4', 'Tradução de Rimas em Jogos', 'Lucas Rodrigues Oliveira', '2025-10-01', '19:00:00', 'A apresentação vai começar abordando a estrutura da poesia, como funcionam as rimas, a métrica, o ritmo e outros elementos que compõem a poesia rimada. Depois, vão ser mostrados vários exemplos de poesias em português para exemplificar esses elementos.\r\nEm seguida, vão ser apresentados exemplos de traduções de poesias (nas duas direções: inglês para português; e português para inglês). No final, o palestrante vai analisar algumas traduções de autoria própria, mostrando como foi o processo criativo.', '/images/announcements/announcement_68d7149763615.png', 1, 5, '2025-09-26 22:32:55', '2025-09-26 22:32:55'),
('6f0ba1631e97fbb1062157ad454a8d60', 'Entre o hilário e o caótico: histórias da interpretação que ninguém te conta', 'Karìne Souto Luana Pires Natália Estrella Patrícia Gimenez Gustavo Assef', '2025-11-06', '20:00:00', 'Neste bate-papo descontraído, mas cheio de informações e estratégias, vamos explorar as histórias da interpretação simultânea nas mídias. A proposta é unir teoria e experiência, compartilhando ideias, ferramentas e histórias reais que inspiram novas formas de pensar, comunicar e agir.\r\nNosso grupo de especialistas, nosso “dream team”, composto por Karine Souto, Luana Pires, Gustavo Assef, Natália Estrella e Patty Gimenez, soma olhares, combina técnicas e gera soluções práticas para desafios reais. A diversidade das formações e trajetórias enriquece as discussões, tornando o grupo um verdadeiro laboratório de ideias e inovações. \r\nMais do que ouvir, o convite é para participar: refletir, trocar vivências e sair daqui com novos olhares e planos possíveis para colocar em prática imediatamente.', '/images/announcements/announcement_68f631a96a8da_2025-10-20.png', 1, 10, '2025-10-20 12:57:13', '2025-10-21 16:57:31'),
('7b58debd0b4205887dd2e9f1449dc314', 'Livros para deixar virados na estante: breve história e macetes para hot', 'Vanessa Thiago', '2025-10-29', '17:00:00', 'Será que romances eróticos são algo moderno? Vamos descobrir juntos e conversar sobre alguns macetes na tradução.', '/images/announcements/announcement_68f27ed590fe0_2025-10-17.png', 1, 8, '2025-10-08 16:43:26', '2025-10-17 17:37:25'),
('7f545d07ec51e5cd6086cb86e2f43dc2', 'Falsos amigos: como identificá-los e estratégias para traduzi-los', 'Mariana Bernicchi', '2025-11-19', '19:00:00', 'Durante a vida, é comum confiar em pessoas traiçoeiras e perceber que isso foi um erro. No aprendizado de línguas, isso também ocorre. O chamado “falso amigo” é, resumidamente, algum termo em língua estrangeira que, por apresentar uma grafia semelhante a qualquer palavra pertencente à língua materna do interlocutor, transforma-se em vocabulário enganoso e gera ruídos de comunicação. Nesta palestra, haverá exemplos que podem ser encontrados em textos simples e documentos, assim como estratégias para evitar traduções equivocadas e, consequentemente, falhas ao transmitir a mensagem. Tentaremos responder à pergunta que paira na mente poliglota: “em quais palavras posso confiar?”', '/images/announcements/announcement_68fb856479190_2025-10-24.png', 1, 11, '2025-10-24 13:55:48', '2025-10-24 13:55:48'),
('ab97bae7ffb03b5990144c4ff330d6e4', 'Neurodiversidade e poliglotismo', 'Erick Gibson e Hewdy Lopes', '2025-10-18', '10:00:00', 'Esta palestra propõe uma reflexão sobre possíveis conexões entre neurodivergência — em especial o Transtorno do Espectro Autista (TEA), o Transtorno do Déficit de Atenção com Hiperatividade (TDAH) e a Alta Habilidade/Superdotação (AHSD) — e o fenômeno do poliglotismo.', '/images/announcements/announcement_68f2c52c320c8_2025-10-17.png', 1, 6, '2025-10-03 14:05:48', '2025-10-17 22:37:32'),
('e8f85f050d85de92b7892c9b603173a7', 'Tradução de Rimas em Jogos', 'Lucas Rodrigues Oliveira', '2025-10-01', '19:00:00', 'A apresentação vai começar abordando a estrutura da poesia, como funcionam as rimas, a métrica, o ritmo e outros elementos que compõem a poesia rimada. Depois, vão ser mostrados vários exemplos de poesias em português para exemplificar esses elementos.\r\nEm seguida, vão ser apresentados exemplos de traduções de poesias (nas duas direções: inglês para português; e português para inglês). No final, o palestrante vai analisar algumas traduções de autoria própria, mostrando como foi o processo criativo.', '/images/announcements/announcement_68d70f359cb21.png', 1, 4, '2025-09-26 22:09:57', '2025-09-26 22:38:50');
