  `password_reset_expires` datetime DEFAULT NULL,
  `hotmart_subscription_id` varchar(255) DEFAULT NULL,
  `is_subscriber` tinyint(1) DEFAULT 0,
  `first_login` tinyint(1) DEFAULT 1,
